const apiFetch = async <T,>(path: string, options: RequestInit = {}): Promise<T> => {
  const headers = new Headers(options.headers); headers.set('Accept', 'application/json');
  if (import.meta.env.DEV) headers.set('x-dev-auth', 'owner');
  const csrf = document.cookie.split('; ').find(item => item.startsWith('br_csrf='))?.split('=').slice(1).join('=');
  if (csrf && options.method && options.method !== 'GET') headers.set('x-br-csrf', decodeURIComponent(csrf));
  let requestOptions = { ...options, headers };
  if (path.endsWith('/check-in') && options.method === 'POST' && typeof options.body === 'string') {
    try { const body = JSON.parse(options.body) as Json; requestOptions = { ...requestOptions, body: JSON.stringify({ ...body, confirmed: true }) }; } catch { /* server validation remains authoritative */ }
  }
  const response = await fetch(path, requestOptions);
  if (response.status === 401) window.dispatchEvent(new Event('br-auth-required'));
  const payload = await response.json().catch(() => null) as Json | null;
  if (!response.ok) throw new Error(String((payload?.error as Json | undefined)?.message ?? 'Request failed'));
  return (payload as { data: T }).data;
}

