function AuthenticatedShell() {
  const [location, setLocation] = useState(parseLocation)
  useEffect(() => {
    const update = () => setLocation(parseLocation())
    window.addEventListener('popstate', update)
    return () => window.removeEventListener('popstate', update)
  }, [])
  const navItems = location.surface === 'office' ? officeItems : mobileItems
  const mobile = location.surface === 'mobile'
  if (mobile) return <div className="v2-shell v2-mobile br-theme-borderless"><OperationalPagesContainer apiFetch={apiFetch} /></div>
  return (
    <div className={`v2-shell v2-${location.surface} br-theme-borderless`}>
      <V2Header surface={location.surface} onLogout={() => window.location.reload()} />
      {location.surface === 'office' && <><V2PrimaryNav active={primaryScreen(location.screen)} onNavigate={(screen, entityId, params) => go('office', screen, entityId, params)} /><V2OfficeSubNav active={location.screen} onNavigate={(screen) => go('office', screen)} /></>}
      <div className="v2-layout">
        {location.surface === 'mobile' && <V2Sidebar surface={location.surface} items={navItems} active={location.screen} onNavigate={(screen) => go(location.surface, screen)} />}
        <main className="v2-main">
          {location.surface === 'mobile' && <V2PageHeader screen={location.screen} surface={location.surface} onNavigate={(screen) => go(location.surface, screen)} />}
          <V2Screen screen={location.screen} surface={location.surface} entityId={location.entityId} panel={location.panel} onNavigate={(screen, entityId, params) => go(location.surface, screen, entityId, params)} />
        </main>
      </div>
      {mobile && <V2BottomNav items={mobileItems} active={location.screen} onNavigate={(screen) => go('mobile', screen)} />}
    </div>
  )
}

function V2Header({ surface, onLogout }: { surface: Surface; onLogout: () => void }) {
  const [open, setOpen] = useState(false); const menuRef = useRef<HTMLDivElement>(null);
  useEffect(() => { if (!open) return; const closeOutside = (event: PointerEvent) => { if (!menuRef.current?.contains(event.target as Node)) setOpen(false) }; const closeEscape = (event: KeyboardEvent) => { if (event.key === 'Escape') setOpen(false) }; document.addEventListener('pointerdown', closeOutside); document.addEventListener('keydown', closeEscape); return () => { document.removeEventListener('pointerdown', closeOutside); document.removeEventListener('keydown', closeEscape) } }, [open]);
  const logout = async () => { try { const registration = await navigator.serviceWorker?.getRegistration('/v2/'); const subscription = await registration?.pushManager.getSubscription(); if (subscription) { await apiFetch('/api/v2/push/subscription', { method: 'DELETE', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ endpoint: subscription.endpoint }) }); await subscription.unsubscribe(); } } catch { /* A push cleanup error must not prevent server-side logout. */ } const csrf = document.cookie.split('; ').find(item => item.startsWith('br_csrf='))?.split('=').slice(1).join('='); const response = await fetch('/auth/logout', { method: 'POST', headers: csrf ? { 'x-br-csrf': decodeURIComponent(csrf) } : {} }); if (response.ok) onLogout(); }
  return <header className="v2-header"><a className="v2-brand" href={`/v2/${surface}/attention`}><img src={logoUrl} alt="Boutique Rooms" /></a><div className="v2-header-actions" ref={menuRef}><button className="v2-icon-button v2-account-button" aria-label="Account menu" aria-expanded={open} onClick={() => setOpen(value => !value)}><UserCircle size={22} /></button>{open && <div className="v2-account-popover" role="dialog" aria-label="Confirm logout"><strong>Log out?</strong><div><button className="v2-button v2-button-secondary" onClick={() => setOpen(false)}>Cancel</button><button className="v2-button v2-button-primary" onClick={() => void logout()}>Log out</button></div></div>}</div></header>
}

function OfficeMonique({ onNavigate }: { onNavigate: (screen: Screen, entityId?: string, params?: Record<string, string>) => void }) {
  const [value, setValue] = useState(''); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async () => {
    if (!value.trim() || busy) return; setBusy(true); setMessage('');
    try {
      const [rooms, people] = await Promise.all([apiFetch<Json[]>('/api/v1/units?limit=100&sort=id&direction=asc'), apiFetch<Json[]>('/api/v1/people?limit=100&sort=updated_at&direction=desc')]);
      const result = resolveOfficeCommand(value, { rooms: rooms.map((row) => ({ id: String(row.id), displayId: String(row.canonical_display_id ?? row.id), unit: String(row.actual_unit_number ?? row.physical_unit_number ?? row.id), occupancy: '', maintenance: '', housekeeping: '', nextDate: '' })), people: people.map((row) => ({ id: String(row.id), name: String(row.display_name ?? row.first_name ?? 'Unnamed person'), role: '', room: '', detail: '' })) });
      if (!result.instruction) { setMessage(result.message ?? result.state); return; }
      const match = officeNavigationRegistry.find(([id]) => id === result.instruction?.destination.navigationId);
      if (!match) { setMessage('Destination is not available.'); return; }
      const screen = match[2] as Screen; const entityId = result.instruction.destination.entities.unitId ?? result.instruction.destination.entities.personId;
      const params = Object.fromEntries(Object.entries(result.instruction.destination.entities).filter(([key]) => key !== 'unitId' && key !== 'personId'));
      onNavigate(screen, entityId, params); setValue('');
    } catch { setMessage('Navigation data unavailable.'); } finally { setBusy(false); }
  };
  return <div className="v2-monique-command"><label><span className="v2-sr-only">Monique command</span><input value={value} onChange={event => setValue(event.target.value)} onKeyDown={event => { if (event.key === 'Enter') void submit(); }} placeholder="Ask Monique to open…" aria-label="Monique command" /></label><button className="v2-button v2-button-secondary" disabled={busy} onClick={() => void submit()} type="button">{busy ? '…' : 'MONIQUE'}</button>{message && <span role="status">{message}</span>}</div>;
}

