function V2ScreenContent({ screen, surface, entityId, panel, onNavigate }: { screen: Screen; surface: Surface; entityId?: string; panel?: string; onNavigate: Navigate }) {
  if (screen === 'listing') return <ListingScreen apiFetch={apiFetch} initialRoomId={entityId} onNavigate={(screenName, nextEntityId) => onNavigate(screenName as Screen, nextEntityId)} />
  if (screen === 'attention') return <AttentionCenter surface={surface} onNavigate={onNavigate} />
  if (screen === 'settings') return <SettingsScreen />
  if (screen === 'more') return <MoreScreen onNavigate={onNavigate} />
  if (screen === 'rooms') return <RoomsScreen requestedRoomId={entityId} />
  if (screen === 'tenancies') return <TenanciesScreen requestedEntityId={entityId} requestedPanel={panel} />
  if (screen === 'maintenance') return <ServiceScreen apiFetch={apiFetch} requestedUnitId={entityId} initialType={panel === 'HOUSEKEEPING' ? 'HOUSEKEEPING' : 'MAINTENANCE'} />
  if (screen === 'inventory') return <InventoryScreen />
  if (screen === 'documents') return <DocumentsScreen />
  if (screen === 'utilities') return <UtilityEntryScreen requestedRoomId={entityId} requestedUtility={panel} />
  if (screen === 'money') return <MoneyScreen />
  if (screen === 'calendar') return <ReferenceCalendarScreen onNavigate={(screenName, entityId, params) => onNavigate(screenName as Screen, entityId, params)} apiFetch={apiFetch} />
  if (screen === 'people' && surface === 'office') return <PeopleScreen requestedPersonId={entityId} />
  if (screen === 'people' && surface === 'mobile') return <PeopleScreen requestedPersonId={entityId} />
  if (screen === 'messages') return <MessagesScreen />
  if (screen === 'normalization-lab') return <NormalizationLabScreen />
  const descriptions: Record<Screen, string> = { attention: 'What needs attention now.', settings: 'Workspace configuration.', more: 'Operational destinations.', listing: 'Rooms and current operating status.', maintenance: 'Open issues and work requiring an owner action.', people: 'People and their relationship with Boutique Rooms.', messages: 'Conversation attention and human follow-up.', 'normalization-lab': 'Deterministic message interpretation without business side effects.', rooms: 'Inventory and date-range availability.', inventory: 'Physical assets and room hierarchy.', documents: 'Operational media references and document metadata.', utilities: 'Meter readings and deterministic summaries.', tenancies: 'Contractual room occupation and historical terms.', leads: 'Qualification facts and owner actions.', calendar: 'Viewings and operational dates.', money: 'Rent schedules and payment records.', content: 'Ideas, shoots and publishing workflow.', analytics: 'Signals from the operation.' }
  return <PlaceholderScreen title={screenLabels[screen]} text={descriptions[screen]} icon={<Activity />} />
}

