function NormalizationLabScreen() {
  const [input, setInput] = useState(''); const [result, setResult] = useState<Json | null>(null); const [error, setError] = useState(''); const [aliases, setAliases] = useState<Json[]>([]); const [alias, setAlias] = useState({ signal_key: 'AVAILABILITY_QUERY', alias: '', language: 'en' });
  const analyze = async (message = input) => { if (!message.trim()) return; setError(''); try { setResult(await apiFetch<Json>('/api/v2/messaging/normalization-lab', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ message }) })); } catch (caught) { setError(caught instanceof Error ? caught.message : 'Analysis failed'); } }
  useEffect(() => { void apiFetch<Json[]>('/api/v2/messaging/aliases').then(setAliases).catch(() => undefined) }, [])
  const addAlias = async () => { if (!alias.alias.trim()) return; try { const created = await apiFetch<Json>('/api/v2/messaging/aliases', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(alias) }); setAliases(current => [...current, created]); setAlias(current => ({ ...current, alias: '' })); } catch (caught) { setError(caught instanceof Error ? caught.message : 'Alias save failed'); } }
  const signals = labRows(result?.signals); const candidates = labRows(result?.domainEventCandidates); const transformations = labRows(result?.transformations); const matched = labRows(result?.matchedAliases); const control = result?.conversationControl as Json | undefined; const summary = result?.summary as Json | undefined;
  return <div className="v2-normalization-lab"><div className="v2-lab-toolbar"><div><p className="v2-eyebrow">MESSAGING / DRY RUN</p><h2>Normalization Lab</h2><p className="v2-page-description">Inspect the real deterministic engine. Analysis has no business side effects.</p></div><button className="v2-button v2-button-primary" onClick={() => void analyze()}>Analyze</button></div>
    <Card title="Customer message" eyebrow="INPUT" icon={<MessagesSquare />}><textarea className="v2-lab-input" value={input} onChange={event => setInput(event.target.value)} onKeyDown={event => { if (event.ctrlKey && event.key === 'Enter') void analyze() }} placeholder="Paste customer message…" aria-label="Customer message" /><div className="v2-lab-case-list">{normalizationCases.map(testCase => <button key={testCase} className="v2-lab-case" onClick={() => { setInput(testCase); void analyze(testCase) }}>{testCase}</button>)}</div>{error && <div className="v2-inline-error">{error}</div>}</Card>
    {result && <div className="v2-lab-results"><Card title="Interpretation" eyebrow="RESULT" icon={<Activity />}><div className="v2-lab-value"><span>RAW INPUT</span><strong>{String(result.rawInput ?? '')}</strong></div><div className="v2-lab-value"><span>NORMALIZED</span><strong>{String(result.normalizedText ?? '')}</strong></div><div className="v2-lab-grid"><div><span className="v2-lab-label">TOKENS</span><p>{labValues(result.tokens).join(' · ') || '—'}</p></div><div><span className="v2-lab-label">NEGATION / CONTEXT</span><p>{String(result.negationContext ?? 'None detected')}</p></div></div></Card>
      <Card title="Signals" eyebrow="CANONICAL TAXONOMY" icon={<SlidersHorizontal />}>{signals.length ? <div className="v2-lab-table">{signals.map((signal, index) => <div className="v2-lab-row" key={`${String(signal.key)}-${index}`}><strong>{String(signal.key)}</strong><span>{signal.value === undefined ? '—' : String(signal.value)}</span><small>persist {String(signal.persist)} · Alan {signal.needsAlan ? 'YES' : 'NO'} · {String(signal.priority)}</small></div>)}</div> : <EmptyState title="No canonical signal" text="The message is noise or below the deterministic confidence threshold." action="No action" onAction={() => undefined} />}</Card>
      <Card title="Explainability" eyebrow="TRANSFORMATIONS / MATCHES" icon={<FileText />}><div className="v2-lab-subsection"><strong>Transformations</strong>{transformations.length ? transformations.map((item, index) => <p key={index}>{String(item.from)} → {String(item.to)} <small>{String(item.reason)}</small></p>) : <p>None</p>}</div><div className="v2-lab-subsection"><strong>Matched aliases</strong>{matched.length ? matched.map((item, index) => <p key={index}>{String(item.alias)} → {String(item.signal_key)} · {String(item.method)}</p>) : <p>None</p>}</div><div className="v2-lab-subsection"><strong>Discarded noise</strong><p>{labRows(result.discardedNoise).map(String).join(' · ') || 'None'}</p></div></Card>
      <Card title="Domain candidates" eyebrow="NO RECORD CREATED" icon={<CalendarDays />}>{candidates.length ? candidates.map((item, index) => <div className="v2-lab-row" key={index}><strong>{String(item.event)}</strong><span>{String(item.date ?? '')} {String(item.time ?? '')}</span><small>{String(item.effect)}</small></div>) : <p className="v2-lab-muted">No domain event candidate.</p>}<div className="v2-lab-control"><strong>LIVE CONTROL WOULD BE</strong><span>{String(control?.mode ?? 'BOT')} · DO_NOT_AUTO_REPLY {control?.doNotAutoReply ? 'YES' : 'NO'} · NEEDS_ALAN {control?.needsAlan ? 'YES' : 'NO'} ({String(control?.priority ?? 'NORMAL')})</span></div><div className="v2-lab-summary"><strong>SUMMARY</strong><span>{labValues(summary?.signals).join(' · ') || 'No persistent signal'}</span><span>Side effects executed: NONE</span></div></Card>
    </div>}
    <Card title="Alias dictionary" eyebrow="CANONICAL EXISTING STORE" icon={<Settings />}><div className="v2-lab-alias-form"><input value={alias.signal_key} onChange={event => setAlias(current => ({ ...current, signal_key: event.target.value }))} placeholder="SIGNAL_KEY" /><input value={alias.alias} onChange={event => setAlias(current => ({ ...current, alias: event.target.value }))} placeholder="alias" /><button className="v2-button v2-button-secondary" onClick={() => void addAlias()}>Add alias</button></div><div className="v2-lab-aliases">{aliases.map(item => <span key={String(item.id)}>{String(item.alias)} → {String(item.signal_key)}</span>)}</div></Card>
  </div>
}

function DocumentsScreen() {
  const [records, setRecords] = useState<Json[]>([]); const [drive, setDrive] = useState<Json | null>(null); const [state, setState] = useState<'loading' | 'ready' | 'error'>('loading');
  useEffect(() => { let active = true; const run = async () => { try { const [data, driveStatus] = await Promise.all([apiFetch<Json[]>('/api/v1/media?include_archived=false'), apiFetch<Json>('/api/v2/drive/status')]); if (active) { setRecords(data); setDrive(driveStatus); setState('ready'); } } catch { if (active) setState('error'); } }; void run(); return () => { active = false; }; }, []);
  return <div className="v2-content-stack"><Card title="Media & documents" eyebrow="BR CORE" icon={<FileText />}><p className="v2-page-description">Operational photos use Cloudinary. IDs and contracts use the private Google Drive connection; D1 stores metadata only.</p>{state === 'loading' && <LoadingState />}{state === 'error' && <AlertState />}{state === 'ready' && <><div className="v2-status-row"><span>Google Drive</span><StatusBadge tone={drive?.status === 'ACTIVE' ? 'accent' : drive?.status === 'ERROR' ? 'alert' : 'quiet'}>{String(drive?.status ?? 'NOT_CONNECTED')}</StatusBadge></div>{drive?.status !== 'ACTIVE' && <Button variant="secondary" onClick={() => { window.location.href = '/auth/google/drive'; }}>Connect Google Drive</Button>}{drive?.status === 'ACTIVE' && <p className="v2-form-note">Connected to {String(drive.root_folder_name ?? 'selected root folder')}. Sensitive files remain private.</p>}{!records.length && <EmptyState title="No media references" text="Add media from the owning Person, Room, tenancy, maintenance issue or asset context." action="No action" onAction={() => undefined} />}{records.map(record => <div className="v2-person-relation" key={String(record.id)}><strong>{String(record.purpose)}</strong><small>{String(record.entity_type)} · {String(record.access_class)} · {formatDate(record.created_at)}</small></div>)}</>}</Card></div>
}

function UtilitiesScreen() {
  const [rooms, setRooms] = useState<Room[]>([]); const [unitId, setUnitId] = useState(''); const [utility, setUtility] = useState('ELECTRICITY'); const [readings, setReadings] = useState<Json[]>([]); const [charges, setCharges] = useState<Json[]>([]); const [state, setState] = useState<'loading' | 'ready' | 'error'>('loading'); const [readingValue, setReadingValue] = useState(''); const addReading = async () => { try { await apiFetch('/api/v1/utilities/readings', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ unit_id: unitId, utility_type: utility, reading_kind: 'INTERMEDIATE', context: 'INTERMEDIATE', reading_value: readingValue, recorded_at: new Date().toISOString() }) }); setReadingValue(''); const data = await apiFetch<Json[]>(`/api/v1/utilities/readings?unit_id=${encodeURIComponent(unitId)}&utility_type=${utility}`); setReadings(data); } catch { setState('error'); } };
  useEffect(() => { void apiFetch<Room[]>('/api/v1/units?limit=100&sort=id&direction=asc').then(data => { setRooms(data); setUnitId(current => current || data[0]?.id || ''); setState('ready'); }).catch(() => setState('error')); }, []);
  useEffect(() => { if (!unitId) return; Promise.all([apiFetch<Json[]>(`/api/v1/utilities/readings?unit_id=${encodeURIComponent(unitId)}&utility_type=${utility}`), apiFetch<Json>(`/api/v1/utilities/charges?unit_id=${encodeURIComponent(unitId)}&utility_type=${utility}`)]).then(([readingData, chargeData]) => { setReadings(readingData); setCharges(Array.isArray(chargeData.charges) ? chargeData.charges : []); setState('ready'); }).catch(() => setState('error')); }, [unitId, utility]);
  return <div className="v2-content-stack"><Card title="Utilities" eyebrow="ROOM OPERATIONS" icon={<Activity />}><div className="v2-people-toolbar"><label className="v2-field"><span>Room</span><select value={unitId} onChange={event => setUnitId(event.target.value)}>{rooms.map(room => <option key={room.id} value={room.id}>{room.id} · {String(room.actual_unit_number ?? '')}</option>)}</select></label><label className="v2-field"><span>Utility</span><select value={utility} onChange={event => setUtility(event.target.value)}><option value="ELECTRICITY">Electricity</option><option value="WATER">Water</option></select></label></div><div className="v2-inline-form"><Field label="New reading" value={readingValue} onChange={setReadingValue} /><Button variant="secondary" onClick={() => void addReading()}>Save reading</Button></div>{state === 'loading' && <LoadingState />}{state === 'error' && <AlertState />}{state === 'ready' && !readings.length && <EmptyState title="No readings" text="Add the first dated reading from the Room or tenancy workflow." action="No action" onAction={() => undefined} />}{readings.map(reading => <div className="v2-person-relation" key={String(reading.id)}><strong>{String(reading.reading_value)} {utility === 'WATER' ? 'm³' : 'kWh'}</strong><small>{String(reading.context ?? 'MANUAL')} · {formatDate(reading.recorded_at)}{reading.tenancy_id ? ` · tenancy ${String(reading.tenancy_id)}` : ' · room-only'}</small></div>)}{charges.map(charge => <div className="v2-status-row" key={`${String(charge.previous_reading_id)}-${String(charge.current_reading_id)}`}><span>{formatDate(charge.period_start)} → {formatDate(charge.period_end)}</span><StatusBadge tone={charge.status === 'CALCULATED' ? 'accent' : 'alert'}>{String(charge.status)}{charge.amount_centavos != null ? ` · ${formatMoney(charge.amount_centavos)}` : ''}</StatusBadge></div>)}</Card></div>
}

function MoneyScreen() {
  const [payments, setPayments] = useState<Json[]>([]); const [state, setState] = useState<'loading' | 'ready' | 'error'>('loading'); const [message, setMessage] = useState('');
  const load = async () => { setState('loading'); try { setPayments(await apiFetch<Json[]>('/api/v1/payments?limit=100')); setState('ready'); } catch { setState('error'); } };
  useEffect(() => { void load(); }, []);
  const postPayment = async (paymentId: string) => { setMessage(''); try { await apiFetch(`/api/v1/payments/${encodeURIComponent(paymentId)}/post`, { method: 'POST', headers: { 'Idempotency-Key': crypto.randomUUID() } }); setMessage('Payment posted to accounting'); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Payment could not be posted'); } };
  const due = payments.filter(payment => ['DUE', 'LATE', 'UPCOMING'].includes(String(payment.status))).reduce((sum, payment) => sum + Number(payment.amount_centavos ?? 0), 0); const paid = payments.filter(payment => payment.status === 'PAID').reduce((sum, payment) => sum + Number(payment.amount_centavos ?? 0), 0);
  return <div className="v2-content-stack"><Card title="Money" eyebrow="OPERATIONAL VIEW" icon={<Wallet />}><div className="v2-status-list"><StatusRow label="Due / upcoming" value={formatMoney(due)} /><StatusRow label="Paid" value={formatMoney(paid)} /></div>{state === 'loading' && <LoadingState />}{state === 'error' && <AlertState />}{state === 'ready' && !payments.length && <EmptyState title="No payment records" text="Accounting and payment records will appear here when real operational data exists." action="No action" onAction={() => undefined} />}{payments.map(payment => <div className="v2-person-relation" key={String(payment.id)}><strong>{formatMoney(payment.amount_centavos)} · {String(payment.status)}</strong><small>{String(payment.type)} · due {String(payment.due_date)} · tenancy {String(payment.tenancy_id)}</small>{payment.status === 'PAID' && !payment.journal_entry_id && <Button variant="secondary" onClick={() => void postPayment(String(payment.id))}>Post to accounting</Button>}</div>)}{message && <p className={message === 'Payment posted to accounting' ? 'v2-save-message' : 'v2-inline-error'}>{message}</p>}</Card></div>
}

const calendarDateKey = (date: Date) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Manila' }).format(date)
const calendarDays = (center: string) => { const anchor = new Date(`${center}T12:00:00+08:00`); const start = new Date(anchor); start.setUTCDate(start.getUTCDate() - start.getUTCDay() - 42); return Array.from({ length: 91 }, (_, index) => { const date = new Date(start); date.setUTCDate(date.getUTCDate() + index); return date.toISOString().slice(0, 10) }) }
const calendarRange = (center: string) => { const start = new Date(`${center}T00:00:00+08:00`); return { from: start.toISOString(), to: new Date(start.getTime() + 46 * 86400000).toISOString() } }
const eventTypeLabel = (event: Json) => String(event.event_type ?? 'OTHER').replaceAll('_', ' ')
const calendarEventWeights: Record<string, number> = { MAINTENANCE: 3, CHECK_IN: 3, CHECK_OUT: 3, VIEWING: 2, RESERVATION: 2, TENANCY_START: 2, TENANCY_EXPIRY: 2, FOLLOW_UP: 1, TASK: 1, PAYMENT: 1 }
const calendarBusyScore = (dayEvents: Json[]) => dayEvents.reduce((total, event) => { const status = String(event.status ?? '').toUpperCase(); if (status === 'CANCELLED' || status === 'COMPLETED' || status === 'RESOLVED' || status === 'CLOSED' || status === 'PAID') return total; const type = String(event.event_type ?? 'OTHER'); const priority = String(event.priority ?? '').toUpperCase(); const priorityWeight = priority === 'URGENT' ? 3 : priority === 'HIGH' ? 2 : priority === 'MEDIUM' ? 1 : 0; return total + (calendarEventWeights[type] ?? 1) + priorityWeight }, 0)
const calendarBusyLevel = (score: number) => score === 0 ? 0 : score <= 2 ? 1 : score <= 5 ? 2 : 3
type CalendarEvent = Json & { event_type?: string; date?: string; start_time?: string | null; end_time?: string | null; person_name?: string | null; room_id?: string | null; status?: string | null; priority?: string | null; channel?: string | null; metadata?: Json }

// Legacy Calendar presentation retained until the remaining Office screens migrate.
export function CalendarScreen({ onNavigate }: { onNavigate: (screen: Screen) => void }) {
  const today = calendarDateKey(new Date());
  const [center, setCenter] = useState(today);
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [selectedDay, setSelectedDay] = useState(today);
  const [filter, setFilter] = useState('ALL');
  const [state, setState] = useState<'loading' | 'ready' | 'error'>('loading');
  const [taskTitle, setTaskTitle] = useState('');
  const [taskDate, setTaskDate] = useState(today);
  const [taskMessage, setTaskMessage] = useState('');
  const days = calendarDays(center);
  const load = async () => {
    setState('loading');
    try {
      const range = calendarRange(center);
      const data = await apiFetch<CalendarEvent[]>(`/api/v2/calendar?${new URLSearchParams(range)}`);
      setEvents(data);
      setState('ready');
    } catch {
      setState('error');
    }
  };
  useEffect(() => { void load(); }, [center]);
  const visibleEvents = events.filter(event => filter === 'ALL' || String(event.event_type) === filter);
  const dayEventsFor = (day: string) => visibleEvents.filter(event => String(event.date) === day);
  const selectedEvents = dayEventsFor(selectedDay);
  const typeCount = (day: string) => [...new Set(dayEventsFor(day).map(event => String(event.event_type)))] as string[];
  const moveCenter = (delta: number) => {
    const date = new Date(`${center}T12:00:00+08:00`);
    date.setUTCDate(date.getUTCDate() + delta);
    setCenter(date.toISOString().slice(0, 10));
  };
  const createTask = async () => {
    if (!taskTitle.trim()) return;
    setTaskMessage('');
    try {
      await apiFetch('/api/v2/tasks', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ title: taskTitle.trim(), due_at: `${taskDate}T09:00:00+08:00`, all_day: true })
      });
      setTaskTitle('');
      setTaskMessage('Task added');
      await load();
    } catch (error) {
      setTaskMessage(error instanceof Error ? error.message : 'Task could not be added');
    }
  };
  const navigateToEvent = (event: Json) => {
    const type = String(event.event_type);
    if (type === 'VIEWING' || type === 'RESERVATION') onNavigate('rooms');
    else if (type === 'MAINTENANCE') onNavigate('maintenance');
    else if (type === 'TASK' || type === 'FOLLOW_UP') onNavigate('attention');
    else if (type === 'PAYMENT') onNavigate('money');
    else if (type === 'CHECK_IN' || type === 'CHECK_OUT' || type.startsWith('TENANCY')) onNavigate('tenancies');
  };
  return (
    <div className="v2-calendar">
      <div className="v2-calendar-toolbar">
        <div>
          <p className="v2-eyebrow">BR CORE / TEMPORAL OPERATIONS</p>
          <h2>Calendar</h2>
          <p className="v2-page-description">A continuous operational date matrix. D1 remains the source of truth; Google Calendar is not used for availability or business state.</p>
        </div>
        <div className="v2-calendar-actions">
          <Button variant="secondary" onClick={() => { setCenter(today); setSelectedDay(today); }}>Today</Button>
          <Button variant="text" onClick={() => moveCenter(-28)}>Earlier</Button>
          <Button variant="text" onClick={() => moveCenter(28)}>Later</Button>
        </div>
      </div>
      <div className="v2-calendar-filters" aria-label="Calendar filters">
        {['ALL', 'VIEWING', 'MAINTENANCE', 'CHECK_IN', 'CHECK_OUT', 'TASK', 'PAYMENT'].map(value => (
          <button type="button" key={value} className={filter === value ? 'is-active' : ''} onClick={() => setFilter(value)}>{value.replaceAll('_', ' ')}</button>
        ))}
      </div>
      {state === 'loading' && <LoadingState />}
      {state === 'error' && <AlertState />}
      {state === 'ready' && (
        <div className="v2-calendar-workspace">
          <div className="v2-calendar-grid-wrap">
            <div className="v2-calendar-matrix" aria-label="90 day operational calendar">
              {days.map(day => {
                const dayEvents = dayEventsFor(day);
                const types = typeCount(day);
                const level = calendarBusyLevel(calendarBusyScore(dayEvents));
                const month = day.endsWith('-01')
                  ? new Intl.DateTimeFormat('en-US', { month: 'short', timeZone: 'Asia/Manila' }).format(new Date(`${day}T12:00:00+08:00`))
                  : '';
                return (
                  <button type="button" key={day} className={`v2-calendar-day busy-${level} ${selectedDay === day ? 'is-selected' : ''} ${day === today ? 'is-today' : ''}`} onClick={() => setSelectedDay(day)} aria-label={`${day}, busy level ${level} of 3, ${dayEvents.length} events, types: ${types.length > 4 ? 'MIXED' : types.join(', ') || 'none'}`}>
                    <strong>{day.slice(8)}</strong>
                    <small>{new Intl.DateTimeFormat('en-US', { weekday: 'short', timeZone: 'Asia/Manila' }).format(new Date(`${day}T12:00:00+08:00`))}</small>
                    {month && <em className="v2-calendar-month">{month}</em>}
                    <span className="v2-calendar-markers">{types.length > 4 ? <i className="is-mixed">MIXED</i> : types.map(type => <i key={type} className={`is-${type.toLowerCase().replaceAll('_', '-')}`} aria-label={type}>{type.slice(0, 3)}</i>)}</span>
                  </button>
                );
              })}
            </div>
            <div className="v2-calendar-agenda">
              <div className="v2-calendar-agenda-heading">
                <DateLabel>{selectedDay === today ? 'TODAY' : selectedDay}</DateLabel>
                <span>{selectedEvents.length} item{selectedEvents.length === 1 ? '' : 's'} · busy {calendarBusyLevel(calendarBusyScore(selectedEvents))}/3</span>
              </div>
              {selectedEvents.length ? selectedEvents.map(event => (
                <article className="v2-calendar-event" key={String(event.projection_id)}>
                  <EntityLabel kind="STATE" onClick={() => navigateToEvent(event)}>{eventTypeLabel(event)}</EntityLabel>
                  {event.start_time && <TimeLabel>{String(event.start_time)}{event.end_time ? `–${String(event.end_time)}` : ''}</TimeLabel>}
                  {event.room_id && <EntityLabel kind="ROOM" onClick={() => onNavigate('rooms')}>{String(event.room_id)}</EntityLabel>}
                </article>
              )) : <EmptyState title="No events on this day" text="Select another date or create a task. No calendar records are fabricated." action="No action" onAction={() => undefined} />}
            </div>
            <div className="v2-calendar-task">
              <strong>Add operational task</strong>
              <div className="v2-inline-form">
                <Field label="Title" value={taskTitle} onChange={setTaskTitle} />
                <Field label="Due date" value={taskDate} type="date" onChange={setTaskDate} />
                <Button variant="secondary" onClick={() => void createTask()}>Save task</Button>
              </div>
              {taskMessage && <p className={taskMessage === 'Task added' ? 'v2-save-message' : 'v2-inline-error'}>{taskMessage}</p>}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

type Person = Json & { id: string; display_name?: string | null; phone?: string | null; email?: string | null; lead_count?: number; latest_lead_status?: string | null; last_activity?: string | null; current_tenancy?: Json | null; labels?: Json[]; requirements?: Json[]; leads?: Json[]; viewings?: Json[]; tenancies?: Json[]; identities?: Json[]; history?: Json[] };

function PeopleScreen({ requestedPersonId }: { requestedPersonId?: string }) {
  const [people, setPeople] = useState<Person[]>([]); const [selectedId, setSelectedId] = useState<string | null>(null); const [search, setSearch] = useState(''); const [sort, setSort] = useState('updated_at'); const [state, setState] = useState<'loading' | 'ready' | 'error'>('loading'); const [creating, setCreating] = useState(false); const [requestedMissing, setRequestedMissing] = useState(false);
  const resolvePeople = async (data: Person[]) => { if (!requestedPersonId || data.some(person => person.id === requestedPersonId)) return data; try { const requested = await apiFetch<Person>(`/api/v1/people/${encodeURIComponent(requestedPersonId)}`); return [requested, ...data]; } catch { return data; } };
  const load = async (searchValue = search) => { setState('loading'); try { const params = new URLSearchParams({ limit: '100', sort, direction: 'desc' }); if (searchValue.trim()) params.set('search', searchValue.trim()); const data = await resolvePeople(await apiFetch<Person[]>(`/api/v1/people?${params}`)); const found = !requestedPersonId || data.some(person => person.id === requestedPersonId); setPeople(data); setRequestedMissing(Boolean(requestedPersonId && !found)); setSelectedId(requestedPersonId ? (found ? requestedPersonId : null) : current => current && data.some(person => person.id === current) ? current : data[0]?.id ?? null); setState('ready'); } catch { setState('error'); } };
  useEffect(() => { let active=true; const run=async()=>{ try { setState('loading'); const data=await resolvePeople(await apiFetch<Person[]>(`/api/v1/people?limit=100&sort=${sort}&direction=desc`)); if(!active)return; const found = !requestedPersonId || data.some(person => person.id === requestedPersonId); setPeople(data); setRequestedMissing(Boolean(requestedPersonId && !found)); setSelectedId(requestedPersonId ? (found ? requestedPersonId : null) : data[0]?.id ?? null); setState('ready'); } catch { if(active)setState('error'); } }; void run(); return ()=>{active=false;}; }, [sort, requestedPersonId]);
  return <div className="v2-people"><div className="v2-people-toolbar"><SearchField value={search} onChange={value => { setSearch(value); void load(value) }} placeholder="Search name, phone or email" /><label className="v2-sort"><span>Sort</span><select value={sort} onChange={event => setSort(event.target.value)}><option value="updated_at">Recently updated</option><option value="last_activity">Last activity</option><option value="name">Name</option><option value="created_at">Created</option></select></label><Button variant="secondary" onClick={() => { setCreating(true); setSelectedId(null); }}>Add person</Button><Button variant="text" onClick={() => void load()}>Refresh</Button></div>{requestedMissing && <div className="v2-inline-error" role="alert">The requested person dossier is unavailable.</div>}{state === 'error' && <div className="v2-inline-error">People could not be loaded. Confirm the local Worker is running and authenticated.</div>}{state === 'loading' && <div className="v2-card"><LoadingState /></div>}{state === 'ready' && <div className="v2-people-workspace"><PersonTable people={people} selectedId={selectedId} onSelect={id => { setCreating(false); setSelectedId(id); }} /><PersonDetail key={creating ? 'new' : `${selectedId ?? 'empty'}-${String(people.find(person => person.id === selectedId)?.updated_at ?? '')}`} person={creating ? null : people.find(person => person.id === selectedId) ?? null} creating={creating} onCreated={async id => { setCreating(false); await load(); setSelectedId(id); }} onSaved={load} onCancel={() => setCreating(false)} /></div>}</div>
}

function PersonTable({ people, selectedId, onSelect }: { people: Person[]; selectedId: string | null; onSelect: (id: string) => void }) {
  return <section className="v2-person-table-wrap"><table className="v2-person-table"><thead><tr><th>Person</th><th>Phone</th><th>Email</th><th>Relationship</th><th>Room</th><th>Last activity</th></tr></thead><tbody>{people.map(person => <tr key={person.id} className={selectedId === person.id ? 'is-selected' : ''} onClick={() => onSelect(person.id)}><td><button className="v2-table-link" onClick={() => onSelect(person.id)}>{String(person.display_name || person.first_name || 'Unnamed person')}</button></td><td>{String(person.phone || '—')}</td><td>{String(person.email || '—')}</td><td>{person.latest_lead_status ? `${person.latest_lead_status} · ${person.lead_count ?? 0} lead(s)` : 'No lead relationship'}</td><td>{person.current_tenancy ? String(person.current_tenancy.room_id ?? 'Assigned') : '—'}</td><td>{formatDate(person.last_activity)}</td></tr>)}</tbody></table>{!people.length && <EmptyState title="No people yet" text="Create a person or wait for a new channel identity to be linked." action="Add person" onAction={() => undefined} />}</section>
}

export function PersonDetail({ person: summary, creating, onCreated, onSaved, onCancel }: { person: Person | null; creating: boolean; onCreated: (id: string) => Promise<void>; onSaved: () => Promise<void>; onCancel: () => void }) {
  const [detail,setDetail]=useState<Person|null>(null);const [detailState,setDetailState]=useState<'loading'|'ready'|'error'>('loading');const [revision,setRevision]=useState(0);
  const person=detail??summary;
  const [tab, setTab] = useState('overview'); const [form, setForm] = useState<Json>(() => person ? { display_name: person.display_name ?? '', first_name: person.first_name ?? '', last_name: person.last_name ?? '', phone: person.phone ?? '', email: person.email ?? '', notes: person.notes ?? '' } : {}); const [message, setMessage] = useState('');
  useEffect(()=>{if(!summary?.id||creating)return;let active=true;setDetailState('loading');void apiFetch<Person>(`/api/v1/people/${encodeURIComponent(summary.id)}`).then(data=>{if(!active)return;setDetail(data);setForm({display_name:data.display_name??'',first_name:data.first_name??'',last_name:data.last_name??'',phone:data.phone??'',email:data.email??'',notes:data.notes??''});setDetailState('ready');}).catch(()=>{if(active)setDetailState('error');});return()=>{active=false;};},[summary?.id,creating,revision]);
  useEffect(()=>{const refresh=()=>setRevision(value=>value+1);window.addEventListener('br-people-refresh',refresh);return()=>window.removeEventListener('br-people-refresh',refresh);},[]);
  if (!person && !creating) return <aside className="v2-person-detail v2-room-detail-empty"><UsersRound size={22} /><p>Select a person to inspect their history.</p></aside>;
  if(!creating&&detailState==='loading')return <aside className="v2-person-detail"><LoadingState /></aside>;
  if(!creating&&detailState==='error')return <aside className="v2-person-detail"><p role="alert">Person dossier could not be loaded.</p><Button onClick={()=>setRevision(value=>value+1)}>Retry</Button></aside>;
  const save = async () => { setMessage(''); try { const data = await apiFetch<Person>(creating ? '/api/v1/people' : `/api/v1/people/${encodeURIComponent(String(person?.id))}`, { method: creating ? 'POST' : 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) }); setMessage('Saved'); if (creating) await onCreated(String(data.id)); else await onSaved(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Save failed'); } };
  const tabs = ['overview', 'contact', 'leads', 'viewings', 'tenancies', 'messages', 'documents', 'notes', 'history'];
  return <aside className="v2-person-detail"><div className="v2-detail-heading"><div><p className="v2-eyebrow">{creating ? 'NEW PERSON' : 'PERSON RECORD'}</p><h2>{creating ? 'Add person' : String(person?.display_name || person?.first_name || 'Unnamed person')}</h2><p>{creating ? 'Create a canonical identity.' : `${person?.lead_count ?? 0} linked lead(s)`}</p></div>{!creating && <div className="v2-contact-actions"><ContactAction href={person?.phone ? `tel:${person.phone}` : undefined} label="Call" icon={<Phone size={15} />} /><ContactAction href={person?.email ? `mailto:${person.email}` : undefined} label="Email" icon={<Mail size={15} />} /></div>}</div><nav className="v2-detail-tabs">{tabs.map(item => <button key={item} className={tab === item ? 'is-active' : ''} onClick={() => setTab(item)}>{item}</button>)}</nav>{tab === 'overview' || tab === 'contact' || tab === 'notes' ? <PersonForm form={form} tab={tab} onChange={(key, value) => setForm(current => ({ ...current, [key]: value }))} /> : creating ? null : <PersonRelationshipView tab={tab} person={person as Person} />}{!creating && tab === 'overview' && person?.identities?.length ? <div className="v2-identity-list"><p className="v2-eyebrow">EXTERNAL IDENTITIES</p>{person.identities.map(identity => <StatusRow key={String(identity.id)} label={String(identity.platform)} value={String(identity.external_id)} />)}</div> : null}<div className="v2-detail-footer"><Button variant="secondary" onClick={onCancel}>Cancel</Button><Button onClick={() => void save()}><Save size={15} />Save</Button>{message && <span className={message === 'Saved' ? 'v2-save-message' : 'v2-inline-error'}>{message}</span>}</div></aside>
}

function PersonForm({ form, tab, onChange }: { form: Json; tab: string; onChange: (key: string, value: string) => void }) {
  return <div className="v2-form-grid">{(tab === 'overview' || tab === 'contact') && <><Field label="Display name" value={String(form.display_name ?? '')} onChange={value => onChange('display_name', value)} /><Field label="First name" value={String(form.first_name ?? '')} onChange={value => onChange('first_name', value)} /><Field label="Last name" value={String(form.last_name ?? '')} onChange={value => onChange('last_name', value)} /><Field label="Phone" value={String(form.phone ?? '')} onChange={value => onChange('phone', value)} /><Field label="Email" value={String(form.email ?? '')} onChange={value => onChange('email', value)} /></>}{(tab === 'overview' || tab === 'notes') && <label className="v2-field v2-field-wide"><span>Notes</span><textarea value={String(form.notes ?? '')} onChange={event => onChange('notes', event.target.value)} /></label>}</div>
}

function PersonDocumentPanel({ person }: { person: Person }) {
  const [file, setFile] = useState<File | null>(null); const [message, setMessage] = useState('');
  const upload = async () => { if (!file) return; try { const form = new FormData(); form.append('entity_type', 'PERSON'); form.append('entity_id', person.id); form.append('purpose', 'PERSON_ID_DOCUMENT'); form.append('file', file); await apiFetch('/api/v2/drive/documents', { method: 'POST', body: form }); setMessage('ID/passport uploaded to private Drive'); setFile(null); } catch (error) { setMessage(error instanceof Error ? error.message : 'Upload failed'); } };
  return <div className="v2-person-relations"><strong>Private ID / passport</strong><input type="file" accept="application/pdf,image/*" capture="environment" onChange={event => setFile(event.target.files?.[0] ?? null)} /><Button variant="secondary" onClick={() => void upload()}>Upload document</Button>{message && <p className="v2-save-message">{message}</p>}</div>;
}

function PersonLabelsPanel({ person }: { person: Person }) {
  const [label,setLabel]=useState(''); const [message,setMessage]=useState(''); const labels=(person.labels ?? []).filter(item=>Number(item.active)!==0);
  const add=async()=>{if(!label.trim())return;try{await apiFetch(`/api/v1/people/${encodeURIComponent(person.id)}/labels`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({label:label.trim(),visibility:'PRIVATE'})});setLabel('');setMessage('✓ Saved');window.dispatchEvent(new Event('br-people-refresh'));}catch{setMessage('Could not save · Retry')}};
  const remove=async(id:string)=>{if(!window.confirm('Remove this private label?'))return;try{await apiFetch(`/api/v1/people/${encodeURIComponent(person.id)}/labels/${encodeURIComponent(id)}`,{method:'DELETE'});setMessage('✓ Saved');window.dispatchEvent(new Event('br-people-refresh'));}catch{setMessage('Could not save · Retry')}};
  return <section className="v2-person-labels"><p className="v2-eyebrow">PRIVATE LABELS</p><div className="v2-label-list">{labels.map(item=><span className="v2-status-badge" key={String(item.id)}>{String(item.label)} <button type="button" aria-label={`Remove ${String(item.label)}`} onClick={()=>void remove(String(item.id))}>×</button></span>)}</div><div className="v2-inline-form"><Field label="Add private label" value={label} onChange={setLabel} /><Button variant="secondary" onClick={()=>void add()}>Add label</Button></div>{message&&<small className={message.startsWith('Could')?'v2-inline-error':'v2-save-message'}>{message}</small>}</section>;
}

function PersonRelationshipView({ tab, person }: { tab: string; person: Person }) {
  if (tab === 'notes') return <><PersonLabelsPanel person={person} /><div className="v2-person-relations"><p className="v2-eyebrow">PRIVATE NOTES</p><p>{String(person.notes ?? 'No private notes yet.')}</p></div></>;
  const values = tab === 'leads' ? person.leads : tab === 'viewings' ? person.viewings : tab === 'tenancies' ? person.tenancies : tab === 'history' ? person.history : [];
  if (tab === 'messages') return <><PersonMessagingMemory person={person} /><PersonLabelsPanel person={person} /></>;
  if (tab === 'documents') return <PersonDocumentPanel person={person} />;
  return <div className="v2-person-relations">{values?.length ? values.map((value, index) => <div className="v2-person-relation" key={String(value.id ?? `${tab}-${index}`)}><strong>{String(value.status ?? value.action ?? value.id ?? 'Record')}</strong><small>{String(value.room_id ?? value.entity_type ?? '')} · {formatDate(value.start_at ?? value.occurred_at ?? value.linked_at)}</small></div>) : <EmptyState title={`No ${tab} records`} text="No records are associated with this person yet." action="No action" onAction={() => undefined} />}</div>
}

function PersonMessagingMemory({person}:{person:Person}) {
  const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);
  const refresh=async()=>{setBusy(true);setMessage('');try{const result=await apiFetch<Json>(`/api/v2/people/${encodeURIComponent(person.id)}/messenger/sync`,{method:'POST'});const sync=result.messenger_sync as Json|undefined;const diagnostics:string[]=[];if(sync?.configuration_missing)diagnostics.push('Messenger profile sync is not configured.');else {if(!sync?.profile_available)diagnostics.push(`Name unavailable${sync?.profile_error_code?` (Meta ${String(sync.profile_error_code)}${sync.profile_error_subcode?`/${String(sync.profile_error_subcode)}`:''})`:''}.`);if(!sync?.conversation_link_available)diagnostics.push(`Conversation link unavailable${sync?.conversation_error_code?` (Meta ${String(sync.conversation_error_code)}${sync.conversation_error_subcode?`/${String(sync.conversation_error_subcode)}`:''})`:''}.`);}setMessage(diagnostics.join(' '));window.dispatchEvent(new Event('br-people-refresh'));}catch(error){setMessage(error instanceof Error?error.message:'Profile refresh failed');}finally{setBusy(false);}};
  const signals=(person.signals??[]) as Json[],attention=(person.attention??[]) as Json[];
  return <section className="v2-person-relations"><p className="v2-eyebrow">PERSON MEMORY · OWNER ONLY</p>{person.identities?.map(identity=><div key={String(identity.id)} className="v2-person-relation"><strong>{String(identity.platform)}</strong><small>{String(identity.external_id)}</small>{identity.conversation_url?<a href={String(identity.conversation_url)} target="_blank" rel="noopener noreferrer">Open conversation</a>:<small>Conversation link not returned by provider.</small>}{identity.platform==='MESSENGER'&&<><small>Profile: {String(identity.profile_sync_status??'Not synced')} · {formatDate(identity.profile_synced_at)}</small><Button variant="secondary" onClick={()=>void refresh()}>{busy?'Refreshing…':'Refresh Messenger profile'}</Button></>}</div>)}<p className="v2-eyebrow">STRUCTURED SIGNALS</p>{signals.length?signals.map(signal=><div className="v2-person-relation" key={`${signal.signal_key}-${signal.normalized_value}`}><strong>{String(signal.signal_key).replaceAll('_',' ')} · {String(signal.normalized_value)}</strong><small>{String(signal.occurrence_count)} occurrence(s) · {String(signal.channels)} · {formatDate(signal.last_seen_at)}</small></div>):<p>No active signals.</p>}{attention.map(item=><StatusRow key={String(item.id)} label={`NEEDS ALAN · ${String(item.priority)}`} value={String(item.signal_key).replaceAll('_',' ')} />)}<p className="v2-eyebrow">QUALIFICATION</p>{person.leads?.map(lead=><div className="v2-person-relation" key={String(lead.id)}><strong>{String(lead.status)} · score {String(lead.interest_score)}{Number(lead.is_hot)?' · HOT':''}</strong><small>Move-in: {String(lead.move_in_date??lead.move_in_precision??'Not shared')} · Stay: {String(lead.duration_months??'Not shared')} months · Occupants: {String(lead.occupancy_count??'Not shared')}</small></div>)}{message&&<p role="alert">{message}</p>}</section>;
}

type MaintenanceIssue = Json & { id: string; unit_id: string; title: string; priority: string; status: string; area: string; asset?: string | null; inventory_asset_id?: string | null; events?: Json[]; room?: Json | null; availability_block?: Json | null; tenancy_context?: Json | null; inventory_asset?: Json | null };

function MaintenanceScreen() {
  const [issues, setIssues] = useState<MaintenanceIssue[]>([]); const [rooms, setRooms] = useState<Room[]>([]); const [selectedId, setSelectedId] = useState<string | null>(null); const [status, setStatus] = useState(''); const [priority, setPriority] = useState(''); const [state, setState] = useState<'loading' | 'ready' | 'error'>('loading'); const [creating, setCreating] = useState(false);
  const load = async () => { setState('loading'); try { const params = new URLSearchParams({ limit: '100' }); if (status) params.set('status', status); if (priority) params.set('priority', priority); const [data, roomData] = await Promise.all([apiFetch<MaintenanceIssue[]>(`/api/v1/maintenance?${params}`), apiFetch<Room[]>('/api/v1/units?limit=100&sort=id&direction=asc')]); setIssues(data); setRooms(roomData); setSelectedId(current => current && data.some(issue => issue.id === current) ? current : data[0]?.id ?? null); setState('ready'); } catch { setState('error'); } };
  useEffect(() => { let active = true; const run = async () => { try { const params = new URLSearchParams({ limit: '100' }); if (status) params.set('status', status); if (priority) params.set('priority', priority); const [data, roomData] = await Promise.all([apiFetch<MaintenanceIssue[]>(`/api/v1/maintenance?${params}`), apiFetch<Room[]>('/api/v1/units?limit=100&sort=id&direction=asc')]); if (!active) return; setIssues(data); setRooms(roomData); setSelectedId(current => current && data.some(issue => issue.id === current) ? current : data[0]?.id ?? null); setState('ready'); } catch { if (active) setState('error'); } }; void run(); return () => { active = false; }; }, [status, priority]);
  return <div className="v2-maintenance"><div className="v2-maintenance-toolbar"><label className="v2-filter"><span>Priority</span><select value={priority} onChange={event => setPriority(event.target.value)}><option value="">All</option><option value="URGENT">Urgent</option><option value="MEDIUM">Medium</option><option value="NORMAL">Normal</option></select></label><label className="v2-filter"><span>Status</span><select value={status} onChange={event => setStatus(event.target.value)}><option value="">Unresolved + history</option><option value="OPEN">Open</option><option value="IN_PROGRESS">In progress</option><option value="WAITING">Waiting</option><option value="RESOLVED">Resolved</option><option value="CLOSED">Closed</option></select></label><Button variant="secondary" onClick={() => { setCreating(true); setSelectedId(null); }}>Add issue</Button><Button variant="text" onClick={() => void load()}>Refresh</Button></div>{state === 'error' && <div className="v2-inline-error">Maintenance could not be loaded. Confirm the local Worker is running and authenticated.</div>}{state === 'loading' && <div className="v2-card"><LoadingState /></div>}{state === 'ready' && <div className="v2-maintenance-workspace"><MaintenanceTable issues={issues} selectedId={selectedId} onSelect={id => { setCreating(false); setSelectedId(id); }} /><MaintenanceDetail issue={creating ? null : issues.find(item => item.id === selectedId) ?? null} rooms={rooms} creating={creating} onCreated={async id => { setCreating(false); await load(); setSelectedId(id); }} onSaved={load} onCancel={() => setCreating(false)} /></div>}</div>;
}

function MaintenanceTable({ issues, selectedId, onSelect }: { issues: MaintenanceIssue[]; selectedId: string | null; onSelect: (id: string) => void }) {
  return <section className="v2-maintenance-table-wrap"><table className="v2-maintenance-table"><thead><tr><th>Room</th><th>Issue</th><th>Area / asset</th><th>Priority</th><th>Status</th><th>Opened</th><th>Impact</th><th>Tenant</th></tr></thead><tbody>{issues.map(issue => <tr key={issue.id} className={selectedId === issue.id ? 'is-selected' : ''} onClick={() => onSelect(issue.id)}><td>{issue.unit_id}</td><td><button className="v2-table-link" onClick={() => onSelect(issue.id)}>{issue.title}</button></td><td>{issue.area}{issue.asset ? ` · ${issue.asset}` : ''}</td><td><PriorityLabel priority={issue.priority} /></td><td><StatusBadge tone={issue.status === 'RESOLVED' || issue.status === 'CLOSED' ? 'quiet' : issue.priority === 'URGENT' ? 'alert' : 'accent'}>{issue.status.replaceAll('_', ' ')}</StatusBadge></td><td>{formatDate(issue.opened_at)}</td><td>{issue.availability_block ? 'Blocked' : 'Not blocked'}</td><td>{String(issue.tenant_name ?? '—')}</td></tr>)}</tbody></table>{!issues.length && <EmptyState title="No maintenance issues" text="No records match the selected filters." action="No action" onAction={() => undefined} />}</section>;
}

function PriorityLabel({ priority, children }: { priority?: unknown; children?: unknown }) { const value = priority ?? children ?? 'NORMAL'; return <span className={`v2-priority v2-priority-${String(value).toLowerCase()}`}><i aria-hidden="true" />{String(value)}</span>; }

function MaintenanceDetail({ issue, rooms, creating, onCreated, onSaved, onCancel }: { issue: MaintenanceIssue | null; rooms: Room[]; creating: boolean; onCreated: (id: string) => Promise<void>; onSaved: () => Promise<void>; onCancel: () => void }) {
  const [form, setForm] = useState<Json>(() => issue ? { unit_id: issue.unit_id, area: issue.area, asset: issue.asset ?? '', inventory_asset_id: issue.inventory_asset_id ?? '', title: issue.title, description: issue.description, priority: issue.priority, status: issue.status, availability_impact: Boolean(issue.availability_block) } : { priority: 'NORMAL', status: 'OPEN', inventory_asset_id: '', availability_impact: false }); const [note, setNote] = useState(''); const [message, setMessage] = useState('');
  if (!issue && !creating) return <aside className="v2-maintenance-detail v2-room-detail-empty"><Wrench size={22} /><p>Select an issue to inspect its history.</p></aside>;
  const update = (key: string, value: string | boolean) => setForm(current => ({ ...current, [key]: value }));
  const save = async () => { setMessage(''); try { const payload = { ...form, inventory_asset_id: form.inventory_asset_id ? String(form.inventory_asset_id) : undefined, availability_start_at: form.availability_start_at ? new Date(String(form.availability_start_at)).toISOString() : undefined, availability_end_at: form.availability_end_at ? new Date(String(form.availability_end_at)).toISOString() : undefined }; const data = await apiFetch<MaintenanceIssue>(creating ? '/api/v1/maintenance' : `/api/v1/maintenance/${encodeURIComponent(String(issue?.id))}`, { method: creating ? 'POST' : 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }); setMessage('Saved'); if (creating) await onCreated(data.id); else await onSaved(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Save failed'); } };
  const addNote = async () => { if (!issue || !note.trim()) return; try { await apiFetch(`/api/v1/maintenance/${encodeURIComponent(issue.id)}/events`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ note }) }); setNote(''); setMessage('Activity saved'); await onSaved(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Activity failed'); } };
  return <aside className="v2-maintenance-detail"><div className="v2-detail-heading"><div><p className="v2-eyebrow">{creating ? 'NEW MAINTENANCE ISSUE' : 'MAINTENANCE ISSUE'}</p><h2>{creating ? 'Add issue' : issue?.title}</h2><p>{creating ? 'Record a structured issue against a Room.' : `${issue?.unit_id} · ${issue?.area}`}</p></div>{!creating && <PriorityLabel priority={issue?.priority ?? 'NORMAL'} />}</div><div className="v2-form-grid"><label className="v2-field"><span>Room</span><select value={String(form.unit_id ?? '')} onChange={event => update('unit_id', event.target.value)}><option value="">Select room</option>{rooms.map(room => <option key={room.id} value={room.id}>{room.id} · {String(room.actual_unit_number ?? '')}</option>)}</select></label><Field label="Area / location" value={String(form.area ?? '')} onChange={value => update('area', value)} /><Field label="Asset / item (optional)" value={String(form.asset ?? '')} onChange={value => update('asset', value)} /><Field label="Inventory asset ID (optional)" value={String(form.inventory_asset_id ?? '')} onChange={value => update('inventory_asset_id', value)} /><Field label="Title" value={String(form.title ?? '')} onChange={value => update('title', value)} /><label className="v2-field v2-field-wide"><span>Description</span><textarea value={String(form.description ?? '')} onChange={event => update('description', event.target.value)} /></label><Field label="Priority" value={String(form.priority ?? 'NORMAL')} select options={['URGENT', 'MEDIUM', 'NORMAL']} onChange={value => update('priority', value)} />{!creating && <Field label="Status" value={String(form.status ?? 'OPEN')} select options={['OPEN', 'IN_PROGRESS', 'WAITING', 'RESOLVED', 'CLOSED']} onChange={value => update('status', value)} />}<label className="v2-feature-check v2-field-wide"><input type="checkbox" checked={form.availability_impact === true} onChange={event => update('availability_impact', event.target.checked)} /><span>Explicitly block Room availability</span></label>{form.availability_impact === true && <><Field label="Block starts" type="datetime-local" value={String(form.availability_start_at ?? '')} onChange={value => update('availability_start_at', value)} /><Field label="Block ends (optional)" type="datetime-local" value={String(form.availability_end_at ?? '')} onChange={value => update('availability_end_at', value)} /></>}</div>{!creating && <><div className="v2-maintenance-context"><StatusRow label="Room" value={String(issue?.unit_id)} /><StatusRow label="Inventory asset" value={String(issue?.inventory_asset?.name ?? issue?.inventory_asset_id ?? 'None')} /><StatusRow label="Availability impact" value={issue?.availability_block ? 'Explicit block' : 'Not blocked'} /><StatusRow label="Tenant context" value={String(issue?.tenancy_context?.display_name ?? 'None')} /></div><div className="v2-activity-form"><Field label="Add dated activity" value={note} onChange={setNote} /><Button variant="secondary" onClick={() => void addNote()}>Add note</Button></div><div className="v2-person-relations">{issue?.events?.map(event => <div className="v2-person-relation" key={String(event.id)}><strong>{String(event.event_type)}</strong><small>{String(event.note)} · {formatDate(event.occurred_at)}</small></div>)}</div></>}<div className="v2-detail-footer"><Button variant="secondary" onClick={onCancel}>Cancel</Button><Button onClick={() => void save()}><Save size={15} />Save</Button>{message && <span className={message === 'Saved' || message === 'Activity saved' ? 'v2-save-message' : 'v2-inline-error'}>{message}</span>}</div></aside>;
}

type InventoryEditorNode = Json & { id:string; scope_unit_id:string|null; parent_id:string|null; level:'MACRO'|'CATEGORY'|'ITEM'; name:string; is_air_conditioner:number; attribute_schema?:string|null; sort_order:number; active:number; state?: { present:'TRUE'|'FALSE'|'UNKNOWN'; quantity:number|null; inverter?:'TRUE'|'FALSE'|'UNKNOWN'|null; hp?:number|null; item_type?:'WINDOW'|'SPLIT'|null; screen_inches?:number|null; bed_size?:'SINGLE'|'DOUBLE'|'QUEEN'|'KING'|null } };
type InventoryEditor = { unit_id:string; nodes:InventoryEditorNode[]; states:Json[]; canonical:Json };

function InventoryScreen() {
  const [rooms, setRooms] = useState<Room[]>([]); const [unitId, setUnitId] = useState('');
  useEffect(() => { void apiFetch<Room[]>('/api/v1/units?limit=100&sort=id&direction=asc').then(data => { setRooms(data); setUnitId(current => current || data[0]?.id || ''); }).catch(() => setRooms([])); }, []);
  return <div className="v2-inventory"><div className="v2-inventory-toolbar"><label className="v2-filter"><span>Room</span><select value={unitId} onChange={event => setUnitId(event.target.value)}><option value="">Select room</option>{rooms.map(room => <option key={room.id} value={room.id}>{room.id} · {String(room.actual_unit_number ?? '')}</option>)}</select></label></div>{unitId ? <InventoryPanel key={unitId} unitId={unitId} rooms={rooms} /> : <EmptyState title="Select a room" text="Inventory belongs to a canonical Room tree." action="No action" onAction={() => undefined} />}</div>;
}

function InventoryPanel({ unitId, rooms = [] }: { unitId: string; rooms?: Room[] }) {
  const [editor, setEditor] = useState<InventoryEditor | null>(null); const [message, setMessage] = useState(''); const [copyFrom, setCopyFrom] = useState(''); const [copyGroups, setCopyGroups] = useState({features:true,inventory:true,terms:true,property:false,commercial:false});
  const load = async () => { try { setEditor(await apiFetch<InventoryEditor>(`/api/v2/inventory/editor?unit_id=${encodeURIComponent(unitId)}`)); setMessage(''); } catch (error) { setMessage(error instanceof Error ? error.message : 'Inventory unavailable'); } };
  useEffect(() => { void load(); }, [unitId]);
  const saveItem = async (node:InventoryEditorNode, patch:Record<string,unknown>) => { try { await apiFetch(`/api/v2/inventory/rooms/${encodeURIComponent(unitId)}/items/${encodeURIComponent(node.id)}`, { method:'PUT', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ unit_id:unitId, catalog_item_id:node.id, present:node.state?.present ?? 'UNKNOWN', quantity:node.state?.quantity ?? null, inverter:node.state?.inverter ?? null, hp:node.state?.hp ?? null, item_type:node.state?.item_type ?? null, screen_inches:node.state?.screen_inches ?? null, bed_size:node.state?.bed_size ?? null, ...patch }) }); setMessage('✓ Saved'); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Could not save · Retry'); } };
  const addNode = async (level:'MACRO'|'CATEGORY'|'ITEM', parentId?:string, roomSpecific = false) => { const name = window.prompt(`New ${level.toLowerCase()} name`); if (!name?.trim()) return; try { await apiFetch('/api/v2/inventory/catalog/nodes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope_unit_id:roomSpecific ? unitId : null,parent_id:parentId ?? null,level,name:name.trim(),is_air_conditioner:name.trim().toLowerCase()==='air conditioner'})}); setMessage(roomSpecific ? 'Room item added' : 'Master taxonomy added'); await load(); } catch(error) { setMessage(error instanceof Error ? error.message : 'Could not add taxonomy item'); } };
  const archive = async (node:InventoryEditorNode) => { if (!node.scope_unit_id || !window.confirm(`Archive ${node.name}?`)) return; try { await apiFetch(`/api/v2/inventory/catalog/nodes/${encodeURIComponent(node.id)}`,{method:'DELETE'}); setMessage('Archived'); await load(); } catch(error) { setMessage(error instanceof Error ? error.message : 'Could not archive item'); } };
  const copy = async () => { if (!copyFrom || !window.confirm(`Copy selected room data from ${copyFrom} into ${unitId}? Existing selected values will be replaced.`)) return; try { await apiFetch('/api/v2/rooms/copy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_unit_id:copyFrom,target_unit_id:unitId,...copyGroups})}); setMessage('Selected room data copied'); await load(); } catch(error) { setMessage(error instanceof Error ? error.message : 'Copy failed'); } };
  const nodes = editor?.nodes ?? []; const macros = nodes.filter(node => node.level==='MACRO' && !node.parent_id); const categories = (macroId:string) => nodes.filter(node => node.level==='CATEGORY' && node.parent_id===macroId); const items = (categoryId:string) => nodes.filter(node => node.level==='ITEM' && node.parent_id===categoryId);
  return <div className="v2-inventory-panel"><div className="v2-inventory-entry"><div className="v2-inventory-toolbar"><strong>Room inventory checklist</strong><Button variant="secondary" onClick={() => void addNode('MACRO')}>+ Macro Category</Button><Button variant="secondary" onClick={() => { void navigator.clipboard?.writeText(JSON.stringify(editor?.canonical ?? {},null,2)); setMessage('Canonical JSON copied'); }}>Copy canonical JSON</Button></div><div className="v2-inventory-copy"><label className="v2-field"><span>Copy from another room</span><select value={copyFrom} onChange={event => setCopyFrom(event.target.value)}><option value="">Select source Room</option>{rooms.filter(room => room.id !== unitId).map(room => <option key={room.id} value={room.id}>{room.id} · {String(room.actual_unit_number ?? '')}</option>)}</select></label>{Object.entries(copyGroups).map(([key,value])=><label className="v2-feature-check" key={key}><input type="checkbox" checked={value} onChange={event=>setCopyGroups(current=>({...current,[key]:event.target.checked}))}/><span>{key}</span></label>)}<Button variant="secondary" disabled={!copyFrom} onClick={() => void copy()}>Copy selected</Button></div></div>{message && <div className="v2-save-message">{message}</div>}<div className="v2-inventory-editor-grid">{macros.map(macro => <section className="v2-inventory-macro" key={macro.id}><header><strong>{macro.name}</strong><div><Button variant="text" onClick={() => void addNode('CATEGORY',macro.id,Boolean(macro.scope_unit_id))}>+ Category</Button>{macro.scope_unit_id && <Button variant="text" onClick={() => void archive(macro)}>Archive</Button>}</div></header>{categories(macro.id).map(category => <div className="v2-inventory-category" key={category.id}><header><strong>{category.name}</strong><div><Button variant="text" onClick={() => void addNode('ITEM',category.id,Boolean(category.scope_unit_id))}>+ Item</Button><Button variant="text" onClick={() => void addNode('ITEM',category.id,true)}>+ Room item</Button>{category.scope_unit_id && <Button variant="text" onClick={() => void archive(category)}>Archive</Button>}</div></header>{items(category.id).map(item => <InventoryItemRow key={item.id} node={item} onSave={patch => void saveItem(item,patch)} onArchive={() => void archive(item)} />)}</div>)}</section>)}</div><details className="v2-inventory-json"><summary>Canonical structured data</summary><pre>{JSON.stringify(editor?.canonical ?? {},null,2)}</pre></details></div>;
}
function InventoryItemRow({ node, onSave, onArchive }: { node:InventoryEditorNode; onSave:(patch:Record<string,unknown>)=>void; onArchive:()=>void }) { const state=node.state ?? {present:'UNKNOWN' as const,quantity:null,inverter:node.is_air_conditioner ? 'UNKNOWN' as const : null,hp:null,item_type:null,screen_inches:null,bed_size:null}; const hasScreen=node.attribute_schema?.includes('screen_inches'); const hasBed=node.id==='inv-item-bed'||node.attribute_schema?.includes('bed_size'); return <div className="v2-inventory-item-row"><span>{node.name}</span><label className="v2-field"><span>Present</span><select value={state.present} onChange={event => onSave({present:event.target.value,quantity:event.target.value==='TRUE' ? (state.quantity ?? 1) : null})}><option>UNKNOWN</option><option>TRUE</option><option>FALSE</option></select></label><div className="v2-inventory-quantity"><button type="button" disabled={state.present!=='TRUE'} onClick={() => onSave({quantity:Math.max(0,(state.quantity ?? 1)-1)})}>−</button><output>{state.present==='TRUE' ? (state.quantity ?? 1) : '—'}</output><button type="button" disabled={state.present!=='TRUE'} onClick={() => onSave({quantity:(state.quantity ?? 0)+1})}>+</button></div>{node.is_air_conditioner===1 && <><label className="v2-field"><span>Type</span><select value={state.item_type ?? ''} onChange={event => onSave({item_type:event.target.value||null})}><option value="">Unknown</option><option>WINDOW</option><option>SPLIT</option></select></label><label className="v2-field"><span>Inverter</span><select value={state.inverter ?? 'UNKNOWN'} onChange={event => onSave({inverter:event.target.value})}><option>UNKNOWN</option><option>TRUE</option><option>FALSE</option></select></label><Field label="HP" type="number" value={state.hp == null ? '' : String(state.hp)} onChange={value => onSave({hp:value ? Number(value) : null})} /></>}{hasScreen&&<Field label="Screen inches" type="number" value={state.screen_inches == null ? '' : String(state.screen_inches)} onChange={value=>onSave({screen_inches:value?Number(value):null})} />}{hasBed&&<label className="v2-field"><span>Bed size</span><select value={state.bed_size ?? ''} onChange={event=>onSave({bed_size:event.target.value||null})}><option value="">Unknown</option><option>SINGLE</option><option>DOUBLE</option><option>QUEEN</option><option>KING</option></select></label>}{node.scope_unit_id && <Button variant="text" onClick={onArchive}>Archive</Button>}</div> }

function ContactAction({ href, label, icon }: { href?: string; label: string; icon: ReactNode }) { return href ? <a className="v2-contact-action" href={href} aria-label={label}>{icon}</a> : null; }
function formatDate(value: unknown) { return value ? new Date(String(value)).toLocaleDateString('en-PH') : '—'; }

type Tenancy = Json & { id: string; person_id?: string | null; unit_id: string; person?: Json | null; room?: Json | null; room_occupancy?: { state: 'VACANT' | 'RESERVED' | 'OCCUPIED' } | null; occupancy_projection?: OccupancyProjection | null; contracts?: Json[]; current_contract?: Json | null; document_requirements?: Json[]; termination?: Json | null; operational?: { check_in?: Json | null; check_out?: Json | null; contract?: Json | null; tenant_id?: Json | null; electricity_opening_reading?: Json | null; water_opening_reading?: Json | null; wifi?: Json | null; documents?: Json[]; readings?: Json[]; checklist?: Record<string, boolean>; incomplete_items?: string[]; complete?: boolean }; attention_state?: string | null };
const dateInputValue = (value: unknown) => value ? String(value).slice(0, 10) : '';
const manilaDateTime = (value: string) => value ? `${value}T00:00:00+08:00` : null;

function TenanciesScreen({ requestedEntityId, requestedPanel }: { requestedEntityId?: string; requestedPanel?: string }) {
  const [tenancies, setTenancies] = useState<Tenancy[]>([]); const [people, setPeople] = useState<Person[]>([]); const [rooms, setRooms] = useState<Room[]>([]); const [selectedId, setSelectedId] = useState<string | null>(null); const [status, setStatus] = useState(''); const [state, setState] = useState<'loading' | 'ready' | 'error'>('loading'); const [creating, setCreating] = useState(false);
  const load = async () => { setState('loading'); try { const [tenancyData, peopleData, roomData] = await Promise.all([apiFetch<Tenancy[]>(`/api/v1/tenancies?limit=100&sort=start_at&direction=desc${status ? `&status=${status}` : ''}`), apiFetch<Person[]>('/api/v1/people?limit=100&sort=name&direction=asc'), apiFetch<Room[]>('/api/v1/units?limit=100&sort=id&direction=asc')]); setTenancies(tenancyData); setPeople(peopleData); setRooms(roomData); const requested = requestedEntityId ? tenancyData.find(item => item.id === requestedEntityId || item.unit_id === requestedEntityId || item.person_id === requestedEntityId) : undefined; setSelectedId(requested?.id ?? (current => current && tenancyData.some(item => item.id === current) ? current : tenancyData[0]?.id ?? null)); setState('ready'); } catch { setState('error'); } };
  useEffect(() => { let active = true; const run = async () => { try { const [tenancyData, peopleData, roomData] = await Promise.all([apiFetch<Tenancy[]>(`/api/v1/tenancies?limit=100&sort=start_at&direction=desc${status ? `&status=${status}` : ''}`), apiFetch<Person[]>('/api/v1/people?limit=100&sort=name&direction=asc'), apiFetch<Room[]>('/api/v1/units?limit=100&sort=id&direction=asc')]); if (!active) return; setTenancies(tenancyData); setPeople(peopleData); setRooms(roomData); const requested = requestedEntityId ? tenancyData.find(item => item.id === requestedEntityId || item.unit_id === requestedEntityId || item.person_id === requestedEntityId) : undefined; setSelectedId(requested?.id ?? (current => current && tenancyData.some(item => item.id === current) ? current : tenancyData[0]?.id ?? null)); setState('ready'); } catch { if (active) setState('error'); } }; void run(); return () => { active = false; }; }, [status, requestedEntityId]);
  return <div className="v2-tenancies"><div className="v2-tenancies-toolbar"><label className="v2-filter"><span>Status</span><select value={status} onChange={event => setStatus(event.target.value)}><option value="">All</option><option value="UPCOMING">Upcoming</option><option value="ACTIVE">Active</option><option value="ENDED">Ended</option><option value="TERMINATED">Terminated</option></select></label><Button variant="secondary" onClick={() => { setCreating(true); setSelectedId(null); }}>Add tenancy</Button><Button variant="text" onClick={() => void load()}>Refresh</Button></div>{state === 'error' && <div className="v2-inline-error">Tenancies could not be loaded. Confirm the local Worker is running and authenticated.</div>}{state === 'loading' && <div className="v2-card"><LoadingState /></div>}{state === 'ready' && <div className="v2-tenancy-workspace"><TenancyTable tenancies={tenancies} selectedId={selectedId} onSelect={id => { setCreating(false); setSelectedId(id); }} /><TenancyDetail key={creating ? 'new' : `${selectedId ?? 'empty'}-${String(tenancies.find(item => item.id === selectedId)?.updated_at ?? '')}-${requestedPanel ?? ''}`} tenancy={creating ? null : tenancies.find(item => item.id === selectedId) ?? null} creating={creating} initialTab={requestedPanel === 'TERMS' ? 'terms' : 'overview'} people={people} rooms={rooms} onCreated={async id => { setCreating(false); await load(); setSelectedId(id); }} onSaved={load} onCancel={() => setCreating(false)} /></div>}</div>;
}

function TenancyTable({ tenancies, selectedId, onSelect }: { tenancies: Tenancy[]; selectedId: string | null; onSelect: (id: string) => void }) {
  return <section className="v2-tenancy-table-wrap"><table className="v2-tenancy-table"><thead><tr><th>Person</th><th>Room</th><th>Occupancy</th><th>Start</th><th>End</th><th>Contracted rent</th><th>Status</th><th>Attention</th></tr></thead><tbody>{tenancies.map(item => <tr key={item.id} className={selectedId === item.id ? 'is-selected' : ''} onClick={() => onSelect(item.id)}><td><button className="v2-table-link" onClick={() => onSelect(item.id)}>{String(item.person?.display_name ?? item.person?.first_name ?? item.tenant_name ?? 'Unnamed person')}</button></td><td>{String(item.unit_id)}</td><td><OccupancyIndicator state={item.room_occupancy?.state ?? 'VACANT'} /><small>Declared {String(item.occupancy_projection?.declared_occupancy ?? 'UNKNOWN')} · Physical {String(item.occupancy_projection?.physical_occupancy_evidence ?? 'NOT_RECORDED')}</small></td><td>{formatDate(item.start_at)}</td><td>{formatDate(item.end_at)}</td><td>{formatMoney(item.monthly_rent_centavos)}</td><td><StatusBadge tone={item.status === 'ACTIVE' ? 'accent' : item.status === 'TERMINATED' ? 'alert' : 'quiet'}>{String(item.status)}</StatusBadge></td><td>{item.attention_state ? String(item.attention_state).replaceAll('_', ' ') : '—'}</td></tr>)}</tbody></table>{!tenancies.length && <EmptyState title="No tenancies yet" text="Create a tenancy only when the person, room and agreed terms are ready." action="No action" onAction={() => undefined} />}</section>;
}

function TenancyDetail({ tenancy, creating, initialTab = 'overview', people, rooms, onCreated, onSaved, onCancel }: { tenancy: Tenancy | null; creating: boolean; initialTab?: string; people: Person[]; rooms: Room[]; onCreated: (id: string) => Promise<void>; onSaved: () => Promise<void>; onCancel: () => void }) {
  const [tab, setTab] = useState(initialTab); const [form, setForm] = useState<Json>(() => tenancy ? { person_id: tenancy.person_id ?? '', unit_id: tenancy.unit_id, start_at: dateInputValue(tenancy.start_at), end_at: dateInputValue(tenancy.end_at), monthly_rent_centavos: tenancy.monthly_rent_centavos, security_deposit_centavos: tenancy.security_deposit_centavos, advance_amount_centavos: tenancy.advance_amount_centavos, payment_due_day: tenancy.payment_due_day, pdc_required: Boolean(tenancy.pdc_required), status: tenancy.status, notes: tenancy.notes ?? '' } : { pdc_required: false, payment_due_day: 1 }); const [message, setMessage] = useState('');
  if (!tenancy && !creating) return <aside className="v2-tenancy-detail v2-room-detail-empty"><ClipboardList size={22} /><p>Select a tenancy to inspect its terms and history.</p></aside>;
  const update = (key: string, value: string | number | boolean | null) => setForm(current => ({ ...current, [key]: value }));
  const save = async () => { setMessage(''); try { const body = { ...form, start_at: manilaDateTime(String(form.start_at ?? '')), end_at: form.end_at ? manilaDateTime(String(form.end_at)) : null, monthly_rent_centavos: Number(form.monthly_rent_centavos), security_deposit_centavos: Number(form.security_deposit_centavos), advance_amount_centavos: Number(form.advance_amount_centavos), payment_due_day: Number(form.payment_due_day) }; const data = await apiFetch<Tenancy>(creating ? '/api/v1/tenancies' : `/api/v1/tenancies/${encodeURIComponent(String(tenancy?.id))}`, { method: creating ? 'POST' : 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); setMessage('Saved'); if (creating) await onCreated(String(data.id)); else await onSaved(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Save failed'); } };
  const tabs = ['overview', 'terms', 'person', 'room', 'payments', 'documents', 'history'];
  return <aside className="v2-tenancy-detail"><div className="v2-detail-heading"><div><p className="v2-eyebrow">{creating ? 'NEW TENANCY' : 'TENANCY RECORD'}</p><h2>{creating ? 'Add tenancy' : String(tenancy?.id)}</h2><p>{creating ? 'Save contractual occupation against one Person and one Room.' : `${String(tenancy?.unit_id)} · ${String(tenancy?.person?.display_name ?? tenancy?.tenant_name ?? 'Person')}`}</p></div>{!creating && <div className="v2-detail-state"><OccupancyIndicator state={tenancy?.room_occupancy?.state ?? 'VACANT'} /><StatusBadge tone={tenancy?.status === 'ACTIVE' ? 'accent' : tenancy?.status === 'TERMINATED' ? 'alert' : 'quiet'}>{String(tenancy?.status)}</StatusBadge></div>}</div><nav className="v2-detail-tabs">{tabs.map(item => <button key={item} className={tab === item ? 'is-active' : ''} onClick={() => setTab(item)}>{item}</button>)}</nav>{tab === 'overview' ? <><TenancyForm tab={tab} form={form} people={people} rooms={rooms} creating={creating} onChange={update} />{!creating && <><HandoverPanel tenancy={tenancy as Tenancy} onSaved={onSaved} /><Rc1ActionsPanel tenancy={tenancy as Tenancy} onSaved={onSaved} /></>}</> : tab === 'terms' ? <><TenancyForm tab={tab} form={form} people={people} rooms={rooms} creating={creating} onChange={update} />{!creating && <ContractLifecycle tenancy={tenancy as Tenancy} onSaved={onSaved} />}</> : creating ? null : <TenancyRelationView tab={tab} tenancy={tenancy as Tenancy} />}{<div className="v2-detail-footer"><Button variant="secondary" onClick={onCancel}>Cancel</Button><Button onClick={() => void save()}><Save size={15} />Save</Button>{message && <span className={message === 'Saved' ? 'v2-save-message' : 'v2-inline-error'}>{message}</span>}</div>}</aside>;
}

function ContractLifecycle({ tenancy, onSaved }: { tenancy: Tenancy; onSaved: () => Promise<void> }) {
  const current = tenancy.current_contract ?? {}; const [start, setStart] = useState(String(current.end_exclusive ?? '').slice(0, 10)); const [end, setEnd] = useState(''); const [lastOccupied, setLastOccupied] = useState(''); const [rent, setRent] = useState(String(current.monthly_rent_centavos ?? tenancy.monthly_rent_centavos ?? '')); const [dueDay, setDueDay] = useState(String(current.monthly_due_day ?? tenancy.payment_due_day ?? '')); const [reason, setReason] = useState(''); const [terminationDate, setTerminationDate] = useState(''); const [busy, setBusy] = useState(false); const [message, setMessage] = useState('');
  const renew = async () => { if (!start || !end || !lastOccupied || !rent || !dueDay) return; setBusy(true); setMessage(''); try { await apiFetch(`/api/v1/tenancies/${encodeURIComponent(tenancy.id)}/contracts`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ start_date: start, end_exclusive: end, last_occupied_date: lastOccupied, monthly_rent_centavos: Number(rent), monthly_due_day: Number(dueDay), expected_payment_day: Math.max(1, Number(dueDay) - 1), deposit_centavos: Number(current.deposit_centavos ?? tenancy.security_deposit_centavos ?? 0), source: 'OFFICE_RENEWAL' }) }); setMessage('Contract version created'); await onSaved(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Contract version failed'); } finally { setBusy(false); } };
  const terminate = async () => { if (!terminationDate || !reason.trim() || !window.confirm('Terminate this tenancy? This preserves history and does not record checkout.')) return; setBusy(true); setMessage(''); try { await apiFetch(`/api/v1/tenancies/${encodeURIComponent(tenancy.id)}/terminate`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ effective_date: terminationDate, reason: reason.trim(), confirmed: true }) }); setMessage('Tenancy terminated'); await onSaved(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Termination failed'); } finally { setBusy(false); } };
  return <section className="v2-handover"><div className="v2-section-heading"><div><p className="v2-eyebrow">CONTRACT HISTORY</p><h3>Effective version</h3></div></div>{tenancy.current_contract ? <div className="v2-status-list"><StatusRow label="Current version" value={`V${String(tenancy.current_contract.version_number)}`} /><StatusRow label="Currency" value={String(tenancy.current_contract.currency_code ?? 'UNKNOWN')} /><StatusRow label="Expected payment day" value={String(tenancy.current_contract.expected_payment_day ?? 'UNKNOWN')} /><StatusRow label="Minimum-term exception" value={tenancy.current_contract.minimum_term_exception ? 'YES' : 'NO'} /><StatusRow label="Physical check-in" value={tenancy.operational?.check_in ? formatDate(tenancy.operational.check_in.actual_check_in_at) : 'NOT RECORDED'} /><StatusRow label="Physical check-out" value={tenancy.operational?.check_out ? formatDate(tenancy.operational.check_out.actual_check_out_at) : 'NOT RECORDED'} /></div> : <p className="v2-form-note">Current contract version: UNKNOWN</p>}<div className="v2-person-relations">{(tenancy.contracts ?? []).map(contract => <div className="v2-person-relation" key={String(contract.id)}><strong>Version {String(contract.version_number)}{tenancy.current_contract?.id === contract.id ? ' · CURRENT' : ''}</strong><small>{String(contract.start_date)} → {String(contract.end_exclusive)} · {formatMoney(contract.monthly_rent_centavos)} · due {String(contract.monthly_due_day ?? 'UNKNOWN')} · expected {String(contract.expected_payment_day ?? 'UNKNOWN')}</small></div>)}{!(tenancy.contracts ?? []).length && <p className="v2-form-note">No contract versions recorded.</p>}</div>{tenancy.termination && <div className="v2-person-relation"><strong>TERMINATED · {String(tenancy.termination.effective_date)}</strong><small>{String(tenancy.termination.reason)} · {String(tenancy.termination.actor)}</small></div>}{tenancy.status !== 'ENDED' && tenancy.status !== 'TERMINATED' && <><div className="v2-handover-item"><strong>Renew / add adjacent version</strong><div className="v2-handover-grid"><Field label="Start date" type="date" value={start} onChange={setStart} /><Field label="Exclusive end" type="date" value={end} onChange={setEnd} /><Field label="Last occupied" type="date" value={lastOccupied} onChange={setLastOccupied} /><Field label="Monthly rent centavos" type="number" value={rent} onChange={setRent} /><Field label="Due day" type="number" value={dueDay} onChange={setDueDay} /></div><Button variant="secondary" disabled={busy} onClick={() => void renew()}>Create contract version</Button></div><div className="v2-handover-item"><strong>Terminate tenancy</strong><Field label="Effective date" type="date" value={terminationDate} onChange={setTerminationDate} /><Field label="Reason" value={reason} onChange={setReason} /><Button variant="secondary" disabled={busy || !terminationDate || !reason.trim()} onClick={() => void terminate()}>Terminate tenancy</Button></div></>}{message && <span className="v2-form-note" role="status">{message}</span>}</section>;
}

function TenancyForm({ tab, form, people, rooms, creating, onChange }: { tab: string; form: Json; people: Person[]; rooms: Room[]; creating: boolean; onChange: (key: string, value: string | number | boolean | null) => void }) {
  if (tab === 'terms') return <div className="v2-form-grid"><Field label="Contracted rent (centavos)" type="number" value={String(form.monthly_rent_centavos ?? '')} onChange={value => onChange('monthly_rent_centavos', Number(value))} /><Field label="Advance (centavos)" type="number" value={String(form.advance_amount_centavos ?? 0)} onChange={value => onChange('advance_amount_centavos', Number(value))} /><Field label="Security deposit (centavos)" type="number" value={String(form.security_deposit_centavos ?? 0)} onChange={value => onChange('security_deposit_centavos', Number(value))} /><Field label="Payment due day" type="number" value={String(form.payment_due_day ?? 1)} onChange={value => onChange('payment_due_day', Number(value))} /><label className="v2-feature-check"><input type="checkbox" checked={form.pdc_required === true} onChange={event => onChange('pdc_required', event.target.checked)} /><span>PDC required</span></label><Field label="Notes" value={String(form.notes ?? '')} onChange={value => onChange('notes', value)} /></div>;
  return <div className="v2-form-grid"><label className="v2-field"><span>Person</span><select value={String(form.person_id ?? '')} onChange={event => onChange('person_id', event.target.value)}><option value="">Select person</option>{people.map(person => <option key={person.id} value={person.id}>{String(person.display_name ?? person.first_name ?? person.id)}</option>)}</select></label><label className="v2-field"><span>Room</span><select value={String(form.unit_id ?? '')} onChange={event => onChange('unit_id', event.target.value)}><option value="">Select room</option>{rooms.map(room => <option key={room.id} value={room.id}>{room.id} · {String(room.actual_unit_number ?? '')}</option>)}</select></label><Field label="Start date" type="date" value={String(form.start_at ?? '')} onChange={value => onChange('start_at', value)} /><Field label="End date" type="date" value={String(form.end_at ?? '')} onChange={value => onChange('end_at', value)} /><Field label="Status" value={String(form.status ?? 'UPCOMING')} select options={['UPCOMING', 'ACTIVE', 'ENDED', 'TERMINATED']} disabled={creating} onChange={value => onChange('status', value)} /><div className="v2-form-note">Date-range availability remains authoritative. Adjacent tenancies are allowed; overlapping active/upcoming tenancies are rejected.</div></div>;
}

function OccupancyIndicator({ state }: { state: 'VACANT' | 'RESERVED' | 'OCCUPIED' | string }) {
  const normalized = state === 'RESERVED' || state === 'OCCUPIED' ? state : 'VACANT';
  return <span className={`v2-occupancy v2-occupancy-${normalized.toLowerCase()}`} aria-label={`Room occupancy: ${normalized}`}><i aria-hidden="true" /><span>{normalized === 'RESERVED' ? 'Reserved / pre-check-in' : normalized[0] + normalized.slice(1).toLowerCase()}</span></span>;
}

function EvidenceCapture({ unitId, onUploaded }: { unitId: string; onUploaded: (id: string) => void }) {
  const [file, setFile] = useState<File | null>(null); const [message, setMessage] = useState('');
  const upload = async () => { if (!file) return; try { const signature = await apiFetch<Json>('/api/v1/media/upload-signature', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ entity_type: 'UNIT', entity_id: unitId, purpose: 'METER_EVIDENCE', transformation_preset: 'METER_EVIDENCE' }) }); const form = new FormData(); form.append('file', file); form.append('api_key', String(signature.api_key)); form.append('timestamp', String(signature.timestamp)); form.append('public_id', String(signature.public_id)); form.append('signature', String(signature.signature)); const uploaded = await fetch(String(signature.upload_url), { method: 'POST', body: form }); if (!uploaded.ok) throw new Error('Photo upload failed'); const asset = await uploaded.json() as Json; const media = await apiFetch<Json>('/api/v1/media', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ provider: 'CLOUDINARY', entity_type: 'UNIT', entity_id: unitId, purpose: 'METER_EVIDENCE', access_class: 'OPERATIONAL', cloudinary_asset_id: asset.asset_id, cloudinary_public_id: asset.public_id, reference_url: asset.secure_url, mime_type: asset.resource_type, format: asset.format, width: asset.width, height: asset.height, byte_size: asset.bytes, transformation_preset: 'METER_EVIDENCE' }) }); onUploaded(String(media.id)); setFile(null); setMessage('Photo attached'); } catch (error) { setMessage(error instanceof Error ? error.message : 'Photo upload failed'); } };
  return <div className="v2-inline-form"><input type="file" accept="image/*" capture="environment" onChange={event => setFile(event.target.files?.[0] ?? null)} /><Button variant="secondary" onClick={() => void upload()}>Attach photo</Button>{message && <small>{message}</small>}</div>;
}

function HandoverPanel({ tenancy, onSaved }: { tenancy: Tenancy; onSaved: () => Promise<void> }) {
  const [electricity, setElectricity] = useState(''); const [water, setWater] = useState(''); const [electricityMediaId, setElectricityMediaId] = useState(''); const [waterMediaId, setWaterMediaId] = useState(''); const [wifiPlan, setWifiPlan] = useState('50 Mbps'); const [wifiSpeed, setWifiSpeed] = useState('50'); const [wifiAmount, setWifiAmount] = useState('84000'); const [documentType, setDocumentType] = useState('CONTRACT'); const [documentReference, setDocumentReference] = useState(''); const [message, setMessage] = useState('');
  const operational = tenancy.operational; const checklist = operational?.checklist ?? {};
  const post = async (path: string, body: Json) => { setMessage(''); try { await apiFetch(`/api/v1/tenancies/${encodeURIComponent(tenancy.id)}${path}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); setMessage('Saved'); await onSaved(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Save failed'); } };
  const now = () => new Date().toISOString();
  return <section className="v2-handover"><div className="v2-section-heading"><div><p className="v2-eyebrow">ROOM HANDOVER</p><h3>Operational check-in</h3></div><OccupancyIndicator state={tenancy.room_occupancy?.state ?? 'VACANT'} /></div><div className="v2-checklist">{[['check_in', 'Check-in recorded'], ['contract_reference', 'Contract reference'], ['tenant_id_reference', 'Tenant ID reference'], ['electricity_opening_reading', 'Electricity opening reading'], ['water_opening_reading', 'Water opening reading'], ['wifi_selection', 'Wi-Fi selection']].map(([key, label]) => <span key={key} className={checklist[key] ? 'is-complete' : ''}><i>{checklist[key] ? '✓' : '!'}</i>{label}</span>)}</div>{!operational?.check_in && <Button variant="secondary" onClick={() => void post('/check-in', { actual_check_in_at: now() })}>Record physical check-in</Button>}<div className="v2-handover-grid"><div className="v2-handover-item"><strong>Opening meter readings</strong><EvidenceCapture unitId={tenancy.unit_id} onUploaded={setElectricityMediaId} /><EvidenceCapture unitId={tenancy.unit_id} onUploaded={setWaterMediaId} /><div className="v2-inline-form"><Field label="Electricity" value={electricity} onChange={setElectricity} /><Button variant="secondary" onClick={() => void post('/meter-readings', { utility_type: 'ELECTRICITY', reading_kind: 'OPENING', reading_value: electricity, recorded_at: now(), media_id: electricityMediaId || undefined })}>Save</Button></div><div className="v2-inline-form"><Field label="Water" value={water} onChange={setWater} /><Button variant="secondary" onClick={() => void post('/meter-readings', { utility_type: 'WATER', reading_kind: 'OPENING', reading_value: water, recorded_at: now(), media_id: waterMediaId || undefined })}>Save</Button></div></div><div className="v2-handover-item"><strong>Wi-Fi service</strong><Field label="Plan" value={wifiPlan} onChange={setWifiPlan} /><div className="v2-inline-form"><Field label="Mbps" type="number" value={wifiSpeed} onChange={setWifiSpeed} /><Field label="Monthly centavos" type="number" value={wifiAmount} onChange={setWifiAmount} /></div><Button variant="secondary" onClick={() => void post('/wifi', { plan_name: wifiPlan, speed_mbps: Number(wifiSpeed), monthly_amount_centavos: Number(wifiAmount), selected_at: now() })}>Save Wi-Fi selection</Button></div><div className="v2-handover-item"><strong>Document reference</strong><label className="v2-field"><span>Type</span><select value={documentType} onChange={event => setDocumentType(event.target.value)}><option value="CONTRACT">Contract</option><option value="TENANT_ID">Tenant ID</option><option value="OTHER">Other</option></select></label><Field label="Reference or link" value={documentReference} onChange={setDocumentReference} /><Button variant="secondary" onClick={() => void post('/documents', { document_type: documentType, reference: documentReference })}>Save document reference</Button></div></div>{message && <span className={message === 'Saved' ? 'v2-save-message' : 'v2-inline-error'}>{message}</span>}</section>;
}

function Rc1ActionsPanel({ tenancy, onSaved }: { tenancy: Tenancy; onSaved: () => Promise<void> }) {
  const [settlement, setSettlement] = useState<Json | null>(null); const [checkoutNote, setCheckoutNote] = useState(''); const [paymentAmount, setPaymentAmount] = useState(''); const [paymentType, setPaymentType] = useState('SECURITY_DEPOSIT'); const [message, setMessage] = useState(''); const [documentFile, setDocumentFile] = useState<File | null>(null); const [readiness, setReadiness] = useState<Json | null>(null); const [deductionAmount, setDeductionAmount] = useState(''); const [deductionReason, setDeductionReason] = useState(''); const [checkoutElectricity, setCheckoutElectricity] = useState(''); const [checkoutWater, setCheckoutWater] = useState(''); const [checkoutElectricityMediaId, setCheckoutElectricityMediaId] = useState(''); const [checkoutWaterMediaId, setCheckoutWaterMediaId] = useState(''); const [conditionMediaId, setConditionMediaId] = useState(''); const [keysReturned, setKeysReturned] = useState('3');
  const loadSettlement = async () => { try { setSettlement(await apiFetch<Json>(`/api/v1/tenancies/${encodeURIComponent(tenancy.id)}/settlement`)); } catch { setMessage('Settlement could not be loaded'); } };  const loadReadiness = async () => { try { setReadiness(await apiFetch<Json>(`/api/v1/units/${encodeURIComponent(tenancy.unit_id)}/readiness`)); } catch { setReadiness(null); } };
  useEffect(() => { void loadSettlement(); void loadReadiness(); }, [tenancy.id]);
  const checkout = async () => { setMessage(''); try { const readings: Json[] = []; for (const [utility_type, reading_value, media_id] of [['ELECTRICITY', checkoutElectricity, checkoutElectricityMediaId], ['WATER', checkoutWater, checkoutWaterMediaId]] as const) { if (reading_value) readings.push(await apiFetch<Json>('/api/v1/utilities/readings', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ unit_id: tenancy.unit_id, tenancy_id: tenancy.id, utility_type, reading_kind: 'CLOSING', context: 'CHECK_OUT', reading_value, recorded_at: new Date().toISOString(), media_id: media_id || undefined }) })); } await apiFetch(`/api/v1/tenancies/${encodeURIComponent(tenancy.id)}/check-out`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ confirmed: true, actual_check_out_at: new Date().toISOString(), electricity_reading_id: readings.find(item => item.utility_type === 'ELECTRICITY')?.id, water_reading_id: readings.find(item => item.utility_type === 'WATER')?.id, condition_media_id: conditionMediaId || undefined, keys_returned: Number(keysReturned), notes: checkoutNote }) }); setMessage('Checkout recorded; turnover is now open'); await onSaved(); await loadReadiness(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Checkout failed'); } };
  const addPayment = async () => { setMessage(''); try { await apiFetch('/api/v1/payments', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Idempotency-Key': crypto.randomUUID() }, body: JSON.stringify({ tenancy_id: tenancy.id, due_date: new Date().toISOString().slice(0, 10), amount_centavos: Number(paymentAmount), type: paymentType, status: 'PAID', paid_at: new Date().toISOString(), method: 'CASH' }) }); setMessage('Payment recorded'); setPaymentAmount(''); await onSaved(); await loadSettlement(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Payment failed'); } };
  const postSettlementAction = async () => { setMessage(''); try { await apiFetch(`/api/v1/tenancies/${encodeURIComponent(tenancy.id)}/settlement/post`, { method: 'POST', headers: { 'Idempotency-Key': crypto.randomUUID() } }); setMessage('Settlement posted; confirm the pending refund or amount due'); await loadSettlement(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Settlement could not be posted'); } };  const addDeduction = async () => { try { await apiFetch(`/api/v1/tenancies/${encodeURIComponent(tenancy.id)}/settlement`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'Idempotency-Key': crypto.randomUUID() }, body: JSON.stringify({ item_type: 'DAMAGE', reason: deductionReason, amount_centavos: Number(deductionAmount), evidence_media_id: conditionMediaId || undefined }) }); setDeductionAmount(''); setDeductionReason(''); await loadSettlement(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Deduction failed'); } }; const approveDeduction = async (id: string) => { try { await apiFetch(`/api/v1/settlement-items/${encodeURIComponent(id)}/approve`, { method: 'POST', headers: { 'Idempotency-Key': crypto.randomUUID() } }); await loadSettlement(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Approval failed'); } };
  const confirmAction = async (id: string) => { try { await apiFetch(`/api/v1/settlement-actions/${encodeURIComponent(id)}/confirm`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'Idempotency-Key': crypto.randomUUID() }, body: JSON.stringify({ method: 'CASH' }) }); setMessage('Settlement action confirmed'); await loadSettlement(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Settlement action failed'); } };
  const ready = Array.isArray(settlement?.actions) ? settlement?.actions as Json[] : [];  const uploadContract = async () => { if (!documentFile) return; setMessage(''); try { const form = new FormData(); form.append('entity_type', 'TENANCY'); form.append('entity_id', tenancy.id); form.append('purpose', 'TENANCY_CONTRACT'); form.append('file', documentFile); await apiFetch('/api/v2/drive/documents', { method: 'POST', body: form }); setMessage('Contract uploaded to private Drive'); setDocumentFile(null); await onSaved(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Document upload failed'); } };  const completeTurnoverTask = async (id: string) => { try { await apiFetch(`/api/v1/turnover/tasks/${encodeURIComponent(id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'DONE' }) }); await loadReadiness(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Turnover update failed'); } };
  return <section className="v2-handover"><div className="v2-section-heading"><div><p className="v2-eyebrow">RC1 OPERATIONS</p><h3>Checkout, money and turnover</h3></div><StatusBadge tone={settlement?.settlement_state === 'SETTLED' ? 'accent' : 'quiet'}>{String(settlement?.settlement_state ?? 'CALCULATED')}</StatusBadge></div>{tenancy.status === 'ACTIVE' && <><Field label="Checkout note" value={checkoutNote} onChange={setCheckoutNote} /><Field label="Electricity closing reading" value={checkoutElectricity} onChange={setCheckoutElectricity} /><EvidenceCapture unitId={tenancy.unit_id} onUploaded={setCheckoutElectricityMediaId} /><Field label="Water closing reading" value={checkoutWater} onChange={setCheckoutWater} /><EvidenceCapture unitId={tenancy.unit_id} onUploaded={setCheckoutWaterMediaId} /><Field label="Keys returned (0–3)" type="number" value={keysReturned} onChange={setKeysReturned} /><EvidenceCapture unitId={tenancy.unit_id} onUploaded={setConditionMediaId} /><Button variant="secondary" onClick={() => void checkout()}>Record checkout and turnover</Button></>}{<><div className="v2-handover-item"><strong>Private contract</strong><input type="file" accept="application/pdf,image/*" onChange={event => setDocumentFile(event.target.files?.[0] ?? null)} capture="environment" /><Button variant="secondary" onClick={() => void uploadContract()}>Upload contract</Button></div><div className="v2-handover-grid"><div className="v2-handover-item"><strong>Record payment</strong><Field label="Amount centavos" type="number" value={paymentAmount} onChange={setPaymentAmount} /><label className="v2-field"><span>Type</span><select value={paymentType} onChange={event => setPaymentType(event.target.value)}><option value="SECURITY_DEPOSIT">Security deposit</option><option value="UTILITY">Utility</option><option value="RENT">Rent</option></select></label><Button variant="secondary" onClick={() => void addPayment()}>Save payment</Button></div><div className="v2-handover-item"><strong>Settlement</strong><Field label="Deduction reason" value={deductionReason} onChange={setDeductionReason} /><Field label="Deduction centavos" type="number" value={deductionAmount} onChange={setDeductionAmount} /><Button variant="secondary" onClick={() => void addDeduction()}>Add deduction</Button>{(settlement?.items as Json[] | undefined)?.filter(item => item.status === 'PROPOSED').map(item => <div className="v2-status-row" key={String(item.id)}><span>{String(item.reason)} · {formatMoney(item.amount_centavos)}</span><Button variant="secondary" onClick={() => void approveDeduction(String(item.id))}>Approve</Button></div>) }<StatusRow label="Deposit held" value={formatMoney(settlement?.security_deposit_held_centavos)} /><StatusRow label="Deductions" value={formatMoney(settlement?.approved_deductions_centavos)} /><StatusRow label="Amount due" value={formatMoney(settlement?.amount_due_centavos)} /><StatusRow label="Refund due" value={formatMoney(settlement?.refund_due_centavos)} /><Button variant="secondary" onClick={() => void postSettlementAction()}>Post settlement</Button></div><div className="v2-handover-item"><strong>Pending financial action</strong>{ready.length ? ready.map(action => <div className="v2-person-relation" key={String(action.id)}><strong>{String(action.action_type)} · {formatMoney(action.amount_centavos)}</strong><Button variant="secondary" onClick={() => void confirmAction(String(action.id))}>Confirm recorded {action.action_type === 'REFUND' ? 'refund' : 'payment'}</Button></div>) : <p className="v2-form-note">No pending action.</p>}</div></div></>}{readiness && <div className="v2-handover-item"><strong>Turnover / readiness: {String(readiness.state)}</strong>{(readiness.tasks as Json[] | undefined)?.map(task => <div className="v2-status-row" key={String(task.id)}><span>{String(task.label)}</span>{task.status === 'DONE' ? <StatusBadge tone="accent">DONE</StatusBadge> : <Button variant="secondary" onClick={() => void completeTurnoverTask(String(task.id))}>Complete</Button>}</div>)}</div>}{message && <span className="v2-save-message">{message}</span>}</section>;
}

function TenancyRelationView({ tab, tenancy }: { tab: string; tenancy: Tenancy }) {
  if (tab === 'payments') return <div className="v2-person-relations">{(tenancy.payments as Json[] | undefined)?.length ? (tenancy.payments as Json[]).map(item => <div className="v2-person-relation" key={String(item.id)}><strong>{String(item.type)} · {formatMoney(item.amount_centavos)}</strong><small>{String(item.status)} · {String(item.due_date)}</small></div>) : <EmptyState title="No payments" text="Payment records remain separate from tenancy terms." action="Not active" onAction={() => undefined} />}</div>;
  if (tab === 'history') return <div className="v2-person-relations">{(tenancy.history as Json[] | undefined)?.length ? (tenancy.history as Json[]).map((item, index) => <div className="v2-person-relation" key={`${String(item.occurred_at)}-${index}`}><strong>{String(item.action)} · {String(item.entity_type)}</strong><small>{formatDate(item.occurred_at)}</small></div>) : <EmptyState title="No history" text="Audited tenancy changes will appear here." action="Not active" onAction={() => undefined} />}</div>;
  if (tab === 'documents') return <div className="v2-person-relations"><div className="v2-section-heading"><div><p className="v2-eyebrow">REQUIREMENTS</p><h3>Document checklist</h3></div></div>{(tenancy.document_requirements ?? []).map(requirement => <div className="v2-person-relation" key={String(requirement.id)}><strong>{String(requirement.document_key)}</strong><small>{String(requirement.status)} · {String(requirement.provenance ?? 'UNKNOWN PROVENANCE')}</small></div>)}{tenancy.operational?.documents?.length ? tenancy.operational.documents.map(document => <div className="v2-person-relation" key={String(document.id)}><strong>{String(document.document_type)}</strong><small>{String(document.reference)} · {formatDate(document.created_at)}</small></div>) : <p className="v2-form-note">No received document references recorded.</p>}</div>;
  const relation = tab === 'person' ? tenancy.person : tenancy.room;
  return <div className="v2-status-list"><StatusRow label={tab === 'person' ? 'Person' : 'Room'} value={String(relation?.display_name ?? relation?.id ?? tenancy[tab === 'person' ? 'person_id' : 'unit_id'] ?? '—')} />{tab === 'room' && <StatusRow label="Occupancy" value={tenancy.room_occupancy?.state ?? 'VACANT'} />}<StatusRow label="Start" value={formatDate(tenancy.start_at)} /><StatusRow label="End" value={formatDate(tenancy.end_at)} /><StatusRow label="Attention" value={String(tenancy.attention_state ?? 'None')} /></div>;
}

function RoomsScreen({ requestedRoomId }: { requestedRoomId?: string }) {
  const [rooms, setRooms] = useState<Room[]>([]); const [selectedId, setSelectedId] = useState<string | null>(null); const [search, setSearch] = useState(''); const [status, setStatus] = useState(''); const [sort, setSort] = useState('id'); const [state, setState] = useState<'loading' | 'ready' | 'error'>('loading');
  const load = async (searchValue = search) => { setState('loading'); try { const params = new URLSearchParams({ limit: '100', sort, direction: 'asc' }); if (searchValue.trim()) params.set('search', searchValue.trim()); if (status) params.set('status', status); const data = await apiFetch<Room[]>(`/api/v1/units?${params}`); setRooms(data); setSelectedId(requestedRoomId && data.some(room => room.id === requestedRoomId) ? requestedRoomId : (current => current && data.some(room => room.id === current) ? current : data[0]?.id ?? null)); setState('ready'); } catch { setState('error'); } };
  useEffect(() => { let active = true; const run = async () => { try { setState('loading'); const params = new URLSearchParams({ limit: '100', sort, direction: 'asc' }); if (status) params.set('status', status); const data = await apiFetch<Room[]>(`/api/v1/units?${params}`); if (!active) return; setRooms(data); setSelectedId(requestedRoomId && data.some(room => room.id === requestedRoomId) ? requestedRoomId : (current => current && data.some(room => room.id === current) ? current : data[0]?.id ?? null)); setState('ready'); } catch { if (active) setState('error'); } }; void run(); return () => { active = false; }; }, [sort, status, requestedRoomId]);
  const selected = rooms.find(room => room.id === selectedId) ?? null;
  return <div className="v2-rooms"><div className="v2-rooms-toolbar"><label className="v2-search"><Search size={16} /><input value={search} onChange={event => setSearch(event.target.value)} onKeyDown={event => { if (event.key === 'Enter') void load(); }} placeholder="Search BR ID, unit or type" /></label><label className="v2-filter"><SlidersHorizontal size={15} /><select value={status} onChange={event => setStatus(event.target.value)}><option value="">All statuses</option><option value="AVAILABLE">Available</option><option value="RESERVED">Reserved</option><option value="OCCUPIED">Occupied</option><option value="MAINTENANCE">Maintenance</option><option value="OFF_MARKET">Off market</option></select></label><label className="v2-sort"><span>Sort</span><select value={sort} onChange={event => setSort(event.target.value)}><option value="id">BR ID</option><option value="floor">Floor</option><option value="sqm">Size</option><option value="status">Status</option><option value="updated_at">Updated</option></select></label><Button variant="secondary" onClick={() => void load()}>Refresh</Button></div>{state === 'error' && <div className="v2-inline-error">Rooms could not be loaded. Confirm the local Worker is running and authenticated.</div>}{state === 'loading' && <div className="v2-card"><LoadingState /></div>}{state === 'ready' && <div className="v2-room-workspace"><RoomTable rooms={rooms} selectedId={selectedId} onSelect={setSelectedId} /><RoomDetail key={selected ? `${selected.id}-${String(selected.updated_at ?? '')}` : 'empty'} room={selected} rooms={rooms} onSaved={load} /></div>}</div>
}

function RoomTable({ rooms, selectedId, onSelect }: { rooms: Room[]; selectedId: string | null; onSelect: (id: string) => void }) {
  return <section className="v2-room-table-wrap"><table className="v2-room-table"><thead><tr><th>BR ID</th><th>Actual unit</th><th>Floor</th><th>Type</th><th>Size</th><th>Occupancy</th><th>Status</th><th>Availability</th><th>Rent</th></tr></thead><tbody>{rooms.map(room => <tr key={room.id} className={selectedId === room.id ? 'is-selected' : ''} onClick={() => onSelect(room.id)}><td><button className="v2-table-link" onClick={() => onSelect(room.id)}>{room.id}</button></td><td>{String(room.actual_unit_number ?? '—')}</td><td>{String(room.floor ?? '—')}</td><td>{String(room.type ?? '—')}</td><td>{String(room.sqm ?? '—')} sqm</td><td><OccupancyIndicator state={room.occupancy_state ?? 'VACANT'} /><small>Declared {String(room.occupancy_projection?.declared_occupancy ?? 'UNKNOWN')} · Physical {String(room.occupancy_projection?.physical_occupancy_evidence ?? 'NOT_RECORDED')}</small></td><td><StatusBadge tone={room.status === 'AVAILABLE' ? 'accent' : room.status === 'OFF_MARKET' ? 'alert' : 'quiet'}>{String(room.status ?? '—')}</StatusBadge></td><td><strong>{String(room.occupancy_projection?.allocation_availability ?? 'UNKNOWN')}</strong><small>{room.next_available_at ? `Next ${formatDate(room.next_available_at)}` : 'No blocker'}</small></td><td>{formatMoney(room.monthly_rent_centavos)}</td></tr>)}</tbody></table>{!rooms.length && <EmptyState title="No rooms match" text="Try another search or status filter." action="Clear filters" onAction={() => undefined} />}</section>
}

function RoomDetail({ room, rooms = [], onSaved }: { room: Room | null; rooms?:Room[]; onSaved: () => Promise<void> }) {
  const [tab, setTab] = useState('identity'); const [form, setForm] = useState<Json>(() => room ? { actual_unit_number: room.actual_unit_number, floor: room.floor, type: room.type, sqm: room.sqm, monthly_rent_centavos: room.monthly_rent_centavos, status: room.status, commercial_priority: room.commercial_priority } : {}); const [featureState, setFeatureState] = useState<Record<string, string | boolean | null>>(() => roomFeatures(room)); const [message, setMessage] = useState(''); const saveTimers = useRef<Record<string, ReturnType<typeof setTimeout>>>({}); const saveSequence = useRef(0);
  if (!room) return <aside className="v2-room-detail v2-room-detail-empty"><BedDouble size={22} /><p>Select a room to inspect its master record.</p></aside>;
  const persist = async (payload:Record<string,unknown>) => { const sequence=++saveSequence.current; setMessage('Saving…'); try { await apiFetch(`/api/v1/units/${encodeURIComponent(room.id)}`, { method:'PATCH', headers:{'Content-Type':'application/json'}, body:JSON.stringify(payload) }); if(sequence===saveSequence.current){setMessage('✓ Saved'); await onSaved();} } catch { if(sequence===saveSequence.current)setMessage('Could not save · Retry'); } };
  const update = (key: string, value: string | number) => { setForm(current => ({ ...current, [key]: value })); if(saveTimers.current[key])clearTimeout(saveTimers.current[key]); saveTimers.current[key]=setTimeout(() => void persist({[key]:key==='floor'||key==='sqm'||key==='monthly_rent_centavos'?Number(value):value}), key==='status'||key==='actual_unit_number'?0:350); };
  const updateFeature = (key:string,value:string|boolean|null) => { setFeatureState(current => ({...current,[key]:value})); void persist({features:{[key]:value}}); };
  const tabs = ['identity','property','commercial','features','inventory','terms','availability'];
  return <aside className="v2-room-detail"><div className="v2-detail-heading"><div><p className="v2-eyebrow">ROOM MASTER RECORD</p><h2>{room.id}</h2><p>{String(room.actual_unit_number)} · Floor {String(room.floor)}</p></div><div className="v2-detail-state"><OccupancyIndicator state={room.occupancy_state ?? 'VACANT'} /><StatusBadge tone={room.status === 'AVAILABLE' ? 'accent' : room.status === 'OFF_MARKET' ? 'alert' : 'quiet'}>{room.status}</StatusBadge></div></div><nav className="v2-detail-tabs">{tabs.map(item => <button key={item} className={tab === item ? 'is-active' : ''} onClick={() => setTab(item)}>{item}</button>)}</nav>{tab === 'identity' || tab === 'property' || tab === 'commercial' ? <RoomForm tab={tab} form={form} features={featureState} onChange={update} onFeatureChange={updateFeature} /> : tab === 'features' ? <RoomFeaturesEditor features={featureState} onChange={updateFeature} /> : tab === 'inventory' ? <RoomInventoryView room={room} rooms={rooms} /> : tab === 'terms' ? <RoomTermsEditor room={room} onSaved={onSaved} /> : tab === 'availability' ? <RoomAvailabilityView room={room} /> : null}<div className="v2-detail-footer">{message && <span className={message.includes('Could') ? 'v2-inline-error' : 'v2-save-message'}>{message}</span>}</div></aside>
}

function RoomInventoryView({ room, rooms = [] }: { room: Room; rooms?:Room[] }) { return <InventoryPanel unitId={room.id} rooms={rooms} /> }
function RoomFeaturesEditor({ features, onChange }: { features:Record<string,string|boolean|null>; onChange:(key:string,value:string|boolean|null)=>void }) { const [custom,setCustom]=useState(''); const keys=['furnished','kitchenette','dedicated_work_area','balcony','panoramic_view','quiet_side','hot_shower','bidet','wifi_ready','usb_c_outlets','universal_outlets']; return <div className="v2-feature-grid">{keys.map(key => <label className="v2-feature-check" key={key}><input type="checkbox" checked={features[key]===true} onChange={event => onChange(key,event.target.checked)} /><span>{key.replaceAll('_',' ')}</span></label>)}<div className="v2-inline-form"><Field label="New feature key" value={custom} onChange={setCustom} /><Button variant="secondary" onClick={() => { const key=custom.trim().toLowerCase().replaceAll(/[^a-z0-9]+/g,'_'); if(key){onChange(key,true);setCustom('');} }}>+ Add Feature</Button></div></div> }
function RoomTermsEditor({ room, onSaved }: { room:Room; onSaved:()=>Promise<void> }) { const [terms,setTerms]=useState<Json>({ standard_minimum_months:3, advance_months:1, security_deposit_months:1, standard_max_occupancy:2, furnished:'TRUE', internet_price_centavos:84000 }); const [message,setMessage]=useState(''); const save=async(key:string,value:unknown)=>{setTerms(current=>({...current,[key]:value}));setMessage('Saving…');try{await apiFetch(`/api/v2/rooms/${encodeURIComponent(room.id)}/master`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({[key]:value})});setMessage('✓ Saved');await onSaved();}catch{setMessage('Could not save · Retry')}}; return <div className="v2-form-grid"><Field label="Minimum months" type="number" value={String(terms.standard_minimum_months)} onChange={value=>void save('standard_minimum_months',Number(value))} /><Field label="Advance months" type="number" value={String(terms.advance_months)} onChange={value=>void save('advance_months',Number(value))} /><Field label="Security deposit months" type="number" value={String(terms.security_deposit_months)} onChange={value=>void save('security_deposit_months',Number(value))} /><Field label="Maximum occupants" type="number" value={String(terms.standard_max_occupancy)} onChange={value=>void save('standard_max_occupancy',Number(value))} /><Field label="Internet price centavos" type="number" value={String(terms.internet_price_centavos)} onChange={value=>void save('internet_price_centavos',Number(value))} /><p className="v2-form-note">Defaults are editable room master facts. Unit overrides are stored separately from live availability.</p>{message&&<span className="v2-save-message">{message}</span>}</div> }
function RoomAvailabilityView({ room }: { room:Room }) { return <div className="v2-status-list"><StatusRow label="Operational status" value={String(room.status)} /><StatusRow label="Occupancy" value={String(room.occupancy_state ?? 'VACANT')} /><StatusRow label="Next available" value={formatDate(room.next_available_at)} /><p className="v2-form-note">Date-range availability remains authoritative in AvailabilityService. This view does not create a second availability source.</p></div> }

function roomFeatures(room: Room | null): Record<string, string | boolean | null> { const features: Record<string, string | boolean | null> = {}; for (const feature of room?.features ?? []) features[feature.feature_key] = feature.feature_value === 'true' ? true : feature.feature_value === 'false' ? false : feature.feature_value ?? ''; return features; }

function RoomForm({ tab, form, features, onChange, onFeatureChange }: { tab: string; form: Json; features: Record<string, string | boolean | null>; onChange: (key: string, value: string | number) => void; onFeatureChange: (key: string, value: string | boolean | null) => void }) {
  if (tab === 'commercial') return <div className="v2-form-grid"><Field label="Asking rent (centavos)" value={String(form.monthly_rent_centavos ?? '')} type="number" onChange={value => onChange('monthly_rent_centavos', Number(value))} /><Field label="Minimum stay" value="3 months" disabled /><Field label="Commercial priority" value={String(form.commercial_priority ?? 'LOW')} select options={['HIGH', 'LOW']} onChange={value => onChange('commercial_priority', value)} /><div className="v2-form-note">Date-specific availability remains authoritative through AvailabilityService.</div></div>;
  if (tab === 'property') return <div className="v2-feature-grid">{['balcony', 'veranda', 'view', 'panoramic_view', 'quiet_side', 'queen_bed', 'sofa_bed'].map(key => <label className="v2-feature-check" key={key}><input type="checkbox" checked={features[key] === true} onChange={event => onFeatureChange(key, event.target.checked)} /><span>{key.replaceAll('_', ' ')}</span></label>)}<Field label="TV inches" value={String(features.tv_inches ?? '')} onChange={value => onFeatureChange('tv_inches', value)} /></div>;
  return <div className="v2-form-grid"><Field label="Actual unit" value={String(form.actual_unit_number ?? '')} onChange={value => onChange('actual_unit_number', value)} /><Field label="Floor" value={String(form.floor ?? '')} type="number" onChange={value => onChange('floor', Number(value))} /><Field label="Room type" value={String(form.type ?? '')} onChange={value => onChange('type', value)} /><Field label="Size sqm" value={String(form.sqm ?? '')} type="number" onChange={value => onChange('sqm', Number(value))} /><Field label="Operational status" value={String(form.status ?? '')} select options={['AVAILABLE', 'RESERVED', 'OCCUPIED', 'MAINTENANCE', 'OFF_MARKET']} onChange={value => onChange('status', value)} /><div className="v2-form-note">The status describes the current operating state; it does not replace date-range availability.</div></div>;
}

function Field({ label, value, onChange, type = 'text', select, options, disabled = false }: { label: string; value: string; onChange?: (value: string) => void; type?: string; select?: boolean; options?: string[]; disabled?: boolean }) {
  if (select) return <UniversalField label={label} kind="select" value={value} disabled={disabled} onChange={onChange} options={(options ?? []).map(option => ({ value: option, label: option }))} />
  return <UniversalField label={label} kind={type === 'tel' || type === 'email' || type === 'number' || type === 'date' || type === 'time' ? type : 'text'} value={value} disabled={disabled} onChange={onChange} />
}

function formatMoney(raw: unknown) { const amount = Number(raw); return Number.isFinite(amount) ? `₱${(amount / 100).toLocaleString('en-PH', { minimumFractionDigits: 0 })}` : '—'; }

function AttentionCenter({ surface, onNavigate }: { surface: Surface; onNavigate: (screen: Screen) => void }) {
  const [items, setItems] = useState<Json[]>([]); const [state, setState] = useState<'loading' | 'ready' | 'error'>('loading'); const [selectedId, setSelectedId] = useState(() => new URLSearchParams(window.location.search).get('attentionId')); const [busyId, setBusyId] = useState('');
  const load = async () => { try { const data = await apiFetch<{ attention?: Json[] }>('/api/v1/dashboard'); setItems(data.attention ?? []); setState('ready'); if (surface === 'mobile') { const clearAppBadge = (navigator as Navigator & { clearAppBadge?: () => Promise<void> }).clearAppBadge; if (typeof clearAppBadge === 'function') void clearAppBadge.call(navigator).catch(() => undefined); } } catch { setState('error'); } };
  useEffect(() => { void load(); }, [surface]);
  const select = (id: string) => { setSelectedId(id); window.history.replaceState({}, '', `${window.location.pathname}?attentionId=${encodeURIComponent(id)}`); };
  const close = () => { setSelectedId(null); window.history.replaceState({}, '', window.location.pathname); };
  const resolve = async (id: string, action: 'CONFIRM' | 'NOT_CONFIRMED') => { setBusyId(id); try { await apiFetch(`/api/v2/messaging/attention/${encodeURIComponent(id)}`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ action }) }); await load(); close(); } finally { setBusyId(''); } };
  const toggleControl = async (item: Json) => { const channel = String(item.channel ?? ''); const conversation = String(item.external_conversation_id ?? ''); if (!channel || !conversation) return; setBusyId(String(item.id)); try { const action = String(item.control_mode ?? 'BOT') === 'HUMAN' ? 'RETURN_TO_BOT' : 'TAKE_OVER'; await apiFetch(`/api/v2/messaging/conversations/${encodeURIComponent(channel)}/${encodeURIComponent(conversation)}/control`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ action }) }); await load(); } finally { setBusyId(''); } };
  return <div className="v2-content-stack">{surface === 'mobile' && <Card className="v2-phone-notifications" title="Phone notifications" eyebrow="BR MOBILE" icon={<Bell />}><MobilePushControls /></Card>}<div className="v2-attention-hero"><div><p className="v2-eyebrow">{surface === 'office' ? 'OWNER OVERVIEW' : 'ATTENTION CENTER'}</p><h2>{surface === 'office' ? 'Keep the operation moving.' : 'What needs your attention?'}</h2><p>{state === 'error' ? 'Live attention data is unavailable.' : items.length ? `${items.length} operational item${items.length === 1 ? '' : 's'} need review.` : 'No live operational items to review.'}</p></div><StatusBadge tone={state === 'error' ? 'alert' : 'quiet'}>{state === 'error' ? 'Unavailable' : 'D1 / BR Core'}</StatusBadge></div>{items.length ? <Card title="Attention" eyebrow="ACTION REQUIRED" icon={<Bell />}><div className="v2-attention-list">{items.map(item => <AttentionItem key={`${String(item.kind)}-${String(item.id)}`} item={item} selected={selectedId === String(item.id)} busy={busyId === String(item.id)} onSelect={select} onClose={close} onResolve={resolve} onToggleControl={toggleControl} />)}</div></Card> : <CardGrid><Card title="Messages" eyebrow="ATTENTION" icon={<MessagesSquare />}><EmptyState title="No message task yet" text="Conversations requiring Alan will appear here." action="Open messages" onAction={() => onNavigate('messages')} /></Card><Card title="People" eyebrow="RELATIONSHIPS" icon={<UsersRound />}><EmptyState title="No people task yet" text="Leads, viewings and tenants will share one identity." action="Open people" onAction={() => onNavigate('people')} /></Card><Card title="Maintenance" eyebrow="OPERATIONS" icon={<Wrench />}><EmptyState title="No maintenance task" text="Open issues and quick actions will appear here." action="Open maintenance" onAction={() => onNavigate('maintenance')} /></Card></CardGrid>}{surface === 'office' && <Card title="System state" eyebrow="BR CORE" icon={<ClipboardList />}><div className="v2-status-list"><StatusRow label="Source of truth" value="D1 / BR Core" /><StatusRow label="Workspace" value="Local foundation" /><StatusRow label="AI mode" value="Not enabled" /></div></Card>}</div>
}

function AttentionItem({ item, selected, busy, onSelect, onClose, onResolve, onToggleControl }: { item: Json; selected: boolean; busy: boolean; onSelect: (id: string) => void; onClose: () => void; onResolve: (id: string, action: 'CONFIRM' | 'NOT_CONFIRMED') => Promise<void>; onToggleControl: (item: Json) => Promise<void> }) {
  const id = String(item.id); const messaging = String(item.kind) === 'MESSAGING'; const botOn = String(item.control_mode ?? 'BOT') !== 'HUMAN';
  return <article className={`v2-attention-card ${selected ? 'is-selected' : ''}`} onClick={() => onSelect(id)}><div className="v2-attention-labels"><span className="v2-attention-label">{String(item.kind)}</span><span className="v2-attention-label">{String(item.priority ?? 'NORMAL')}</span><span className="v2-attention-label">{String(item.channel ?? item.status ?? 'OPEN')}</span></div><div className="v2-attention-summary"><strong>{String(item.display_name ?? item.title ?? item.label ?? 'Review')}</strong><span>{String(item.signal_key ?? item.title ?? item.label ?? item.status ?? 'Review').replaceAll('_', ' ')}</span></div>{selected && <div className="v2-attention-workspace" onClick={event => event.stopPropagation()}><div className="v2-attention-labels"><span className="v2-attention-label">STATUS: {String(item.status ?? 'OPEN')}</span><span className="v2-attention-label">BOT: {botOn ? 'ON' : 'OFF'}</span></div>{item.value_json != null && <div className="v2-attention-detail"><strong>DETAIL</strong><span>{String(item.value_json)}</span></div>}<div className="v2-attention-actions"><Button variant="primary" disabled={busy} onClick={() => void onResolve(id, 'CONFIRM')}>CONFIRM</Button><Button variant="secondary" disabled={busy} onClick={() => void onResolve(id, 'NOT_CONFIRMED')}>NOT CONFIRMED</Button>{messaging && <span className="v2-bot-switch"><span className="v2-bot-switch-label">BOT {botOn ? 'ON' : 'OFF'}</span><ToggleSwitch checked={botOn} onChange={() => void onToggleControl(item)} label={`Bot replies ${botOn ? 'on' : 'off'}`} disabled={busy || !item.external_conversation_id} /></span>}{Boolean(item.conversation_url) && <a className="v2-button v2-button-secondary" href={String(item.conversation_url)} target="_blank" rel="noopener noreferrer">OPEN CONVERSATION <ArrowRight size={14} /></a>}{selected && <button type="button" className="v2-button v2-button-text" onClick={onClose}>CLOSE</button>}</div></div>}</article>
}

function MobilePushControls() {
  const [state, setState] = useState<'checking' | 'ready' | 'enabled' | 'not-installed' | 'denied' | 'unsupported' | 'error'>('checking');
  const [busy, setBusy] = useState(false); const [message, setMessage] = useState('');
  const ios = typeof navigator !== 'undefined' && /iPhone|iPad|iPod/i.test(navigator.userAgent);
  const installed = typeof window !== 'undefined' && (window.matchMedia('(display-mode: standalone)').matches || Boolean((navigator as Navigator & { standalone?: boolean }).standalone));
  const check = async () => {
    if (!('serviceWorker' in navigator) || !('PushManager' in window) || !('Notification' in window)) { setState('unsupported'); return; }
    if (ios && !installed) { setState('not-installed'); return; }
    if (Notification.permission === 'denied') { setState('denied'); return; }
    try { const registration = await navigator.serviceWorker.getRegistration('/v2/'); const subscription = await registration?.pushManager.getSubscription(); setState(subscription && Notification.permission === 'granted' ? 'enabled' : 'ready'); }
    catch { setState('ready'); }
  };
  useEffect(() => { void check(); }, []);
  const enable = async () => {
    setMessage('');
    if (ios && !installed) { setState('not-installed'); return; }
    if (!('serviceWorker' in navigator) || !('PushManager' in window) || !('Notification' in window)) { setState('unsupported'); return; }
    setBusy(true);
    try {
      // Request permission directly from this user gesture; iOS rejects deferred prompts.
      const permissionRequest = Notification.requestPermission();
      const permission = await permissionRequest;
      if (permission !== 'granted') { setState(permission === 'denied' ? 'denied' : 'ready'); return; }
      const registration = await navigator.serviceWorker.register('/sw-v2.js', { scope: '/v2/' });
      await navigator.serviceWorker.ready;
      const { public_key } = await apiFetch<{ public_key: string }>('/api/v2/push/public-key', { method: 'POST', body: '{}' });
      let subscription = await registration.pushManager.getSubscription();
      if (!subscription) {
        const binary = Uint8Array.from(atob(public_key.replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(public_key.length / 4) * 4, '=')), character => character.charCodeAt(0));
        subscription = await registration.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: binary });
      }
      await apiFetch('/api/v2/push/subscription', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(subscription.toJSON()) });
      setState('enabled'); setMessage('Push notifications are active on this phone.');
    } catch (error) { setState('error'); setMessage(error instanceof Error ? error.message : 'Could not enable notifications.'); }
    finally { setBusy(false); }
  };
  const toggle = async () => { if (state === 'enabled') { await disable(); return; } await enable(); };
  const sendTest = async () => { setBusy(true); setMessage(''); try { const result = await apiFetch<{ sent: number; failed: number }>('/api/v2/push/test', { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{}' }); setMessage(result.sent ? 'Test notification sent.' : 'The push service did not accept the test notification.'); if (result.failed) setState('error'); } catch (error) { setMessage(error instanceof Error ? error.message : 'Test notification failed.'); } finally { setBusy(false); } };
  const disable = async () => { setBusy(true); setMessage(''); try { const registration = await navigator.serviceWorker.getRegistration('/v2/'); const subscription = await registration?.pushManager.getSubscription(); if (subscription) { await apiFetch('/api/v2/push/subscription', { method: 'DELETE', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ endpoint: subscription.endpoint }) }); await subscription.unsubscribe(); } setState('ready'); setMessage('Notifications disabled for this phone.'); } catch (error) { setMessage(error instanceof Error ? error.message : 'Could not disable notifications.'); } finally { setBusy(false); } };
  return <div className="v2-push-controls"><div className="v2-push-toggle-row"><span><strong>Enable notifications</strong><small>{state === 'enabled' ? 'ON · Owner alerts enabled on this phone' : state === 'not-installed' ? 'Add BR Mobile to the Home Screen first' : state === 'unsupported' ? 'Not supported in this browser context' : state === 'denied' ? 'Blocked in iPhone notification settings' : 'OFF · Enable owner alerts on this phone'}</small></span><ToggleSwitch checked={state === 'enabled'} onChange={() => void toggle()} label="Enable notifications" disabled={busy || state === 'checking' || state === 'unsupported' || state === 'denied' || state === 'not-installed'} /></div>{state === 'enabled' && <button className="v2-button v2-button-secondary" disabled={busy} onClick={() => void sendTest()}>{busy ? 'Sending…' : 'Send test notification'}</button>}{state === 'not-installed' && <p>On iPhone, add this page to the Home Screen and open BR Mobile from that icon. Chrome supports Add to Home Screen too.</p>}{state === 'denied' && <p>Turn notifications on for BR Mobile in iPhone Settings, then return here.</p>}{state === 'unsupported' && <p>Open the installed BR Mobile Home Screen app to enable push notifications.</p>}{message && <p role="status" aria-live="polite">{message}</p>}</div>
}

function MoreScreen({ onNavigate }: { onNavigate: (screen: Screen) => void }) {
  const destinations: { screen: Screen; label: string; text: string; icon: ReactNode }[] = [
    { screen: 'maintenance', label: 'Services', text: 'Maintenance and housekeeping tasks', icon: <Wrench /> },
    { screen: 'rooms', label: 'Rooms', text: 'Inventory and availability', icon: <BedDouble /> },
    { screen: 'calendar', label: 'Calendar', text: 'Viewings and dates', icon: <CalendarDays /> },
    { screen: 'money', label: 'Money', text: 'Rent and payments', icon: <Wallet /> },
    { screen: 'content', label: 'Content', text: 'Ideas and publishing', icon: <FileText /> },
    { screen: 'documents', label: 'Documents', text: 'Media references and files', icon: <FileText /> },
    { screen: 'inventory', label: 'Inventory', text: 'Room asset trees', icon: <SlidersHorizontal /> },
    { screen: 'utilities', label: 'Utilities', text: 'Meter readings', icon: <Activity /> },
    { screen: 'analytics', label: 'Analytics', text: 'Operational signals', icon: <Activity /> },
    { screen: 'settings', label: 'Settings', text: 'Workspace configuration', icon: <Settings /> },
  ]
  return <div className="v2-more-grid">{destinations.map((item) => <button className="v2-destination" key={item.screen} onClick={() => onNavigate(item.screen)}><span className="v2-destination-icon">{item.icon}</span><span><strong>{item.label}</strong><small>{item.text}</small></span><ArrowRight size={15} /></button>)}</div>
}

void MaintenanceScreen;
function SettingsScreen() {
  const [enabled, setEnabled] = useState(false)
  const [showStatus, setShowStatus] = useState(true); const [choice, setChoice] = useState('VIEWING'); const [segment, setSegment] = useState('ALL')
  return <div className="v2-content-stack"><Card title="Workspace controls" eyebrow="FOUNDATION" icon={<Settings />}><div className="v2-control-list"><Checkbox label="Show operational status" checked={showStatus} onChange={setShowStatus} /><div className="v2-toggle-row"><span><strong>AI mode</strong><small>Reserved for a future selectable engine.</small></span><ToggleSwitch label="AI mode" checked={enabled} onChange={setEnabled} /></div></div></Card><Card title="Universal controls" eyebrow="BR OS DESIGN SYSTEM" icon={<ClipboardList />}><div className="br-showcase"><UniversalField label="Name" value="Maria Santos" readOnly /><UniversalField label="Type · Dropdown" kind="select" value={choice} onChange={setChoice} options={[{ value: 'VIEWING', label: 'Viewing' }, { value: 'TENANCY', label: 'Tenancy' }]} /><UniversalField label="Message · Multiline" kind="textarea" value="Please confirm your availability for the viewing." onChange={() => undefined} /><div className="br-showcase-row"><ActionButton>Confirm</ActionButton><ActionButton variant="secondary">Not confirmed</ActionButton></div><SegmentedControl value={segment} onChange={setSegment} options={[{ value: 'ALL', label: 'All' }, { value: 'OPEN', label: 'Open' }]} /><div className="br-showcase-row"><Radio label="Viewing" name="showcase-kind" value="VIEWING" checked={choice === 'VIEWING'} onChange={setChoice} /><Radio label="Tenancy" name="showcase-kind" value="TENANCY" checked={choice === 'TENANCY'} onChange={setChoice} /></div></div></Card><Card title="States" eyebrow="COMPONENTS" icon={<ClipboardList />}><AlertState /><LoadingState /><EmptyState title="No configuration yet" text="Future dictionaries and integrations will be managed here." action="Review settings" onAction={() => undefined} /></Card><ActionSheetFoundation /></div>
}

function AlertState() { return <div className="v2-alert-state"><span><Bell size={16} /></span><p><strong>Attention state</strong><small>Used when Alan needs to make a decision.</small></p></div> }
function LoadingState() { return <div className="v2-loading-state"><span className="v2-loading-line" /><span className="v2-loading-line short" /></div> }
function ActionSheetFoundation() { return <div className="v2-action-sheet-preview"><p className="v2-eyebrow">ACTION SHEET FOUNDATION</p><p>Reserved for contextual mobile actions that need more than an icon.</p><Button variant="secondary">Preview action context</Button></div> }

function PlaceholderScreen({ title, text, icon }: { title: string; text: string; icon: ReactNode }) {
  return <FolderWorkspace className="v2-placeholder-workspace"><Card title="Foundation shell" eyebrow="NOT ACTIVE" icon={icon}><div className="v2-placeholder"><div className="v2-placeholder-icon">{icon}</div><h2>{title}</h2><p>{text}</p><StatusBadge tone="quiet">Coming next</StatusBadge></div></Card></FolderWorkspace>
}

function Submenu({ label, options, onSelect }: { label: string; options: string[]; onSelect: () => void }) {
  return <details className="v2-submenu"><summary><span>{label}</span><ChevronDown size={15} /></summary><div className="v2-submenu-panel">{options.map((option) => <button key={option} onClick={onSelect}>{option}</button>)}</div></details>
}

function CardGrid({ children, className = '' }: { children: ReactNode; className?: string }) {
  return <div className={`v2-card-grid ${className}`.trim()}>{children}</div>
}

function FolderWorkspace({ children, className = '' }: { children: ReactNode; className?: string }) {
  return <section className={`v2-folder-workspace ${className}`.trim()}>{children}</section>
}

function Card({ title, eyebrow, icon, children, className = '' }: { title: string; eyebrow: string; icon: ReactNode; children: ReactNode; className?: string }) {
  return <motion.article className={`v2-card v2-folder-card ${className}`.trim()} whileHover={{ y: -2 }} transition={{ duration: 0.14, ease: 'easeOut' }}><div className="v2-card-heading"><div><p className="v2-eyebrow">{eyebrow}</p><h2>{title}</h2></div><span className="v2-card-icon">{icon}</span></div>{children}</motion.article>
}

function EmptyState({ title, text, action, onAction }: { title: string; text: string; action: string; onAction: () => void }) {
  return <div className="v2-empty"><span className="v2-empty-mark"><Check size={16} /></span><div><strong>{title}</strong><p>{text}</p></div><Button variant="text" onClick={onAction}>{action}<ArrowRight size={14} /></Button></div>
}

function StatusBadge({ children, tone }: { children: ReactNode; tone: 'quiet' | 'alert' | 'accent' }) {
  return <span className={`v2-badge v2-badge-${tone}`}>{children}</span>
}

function StatusRow({ label, value }: { label: string; value: string }) {
  return <div className="v2-status-row"><span>{label}</span><StatusBadge tone="quiet">{value}</StatusBadge></div>
}

function Button({ children, variant = 'primary', onClick, disabled = false }: { children: ReactNode; variant?: 'primary' | 'secondary' | 'text'; onClick?: () => void; disabled?: boolean }) {
  return <ActionButton variant={variant} disabled={disabled} onClick={onClick}>{children}</ActionButton>
}

function UtilityEntryScreen({ requestedRoomId, requestedUtility }: { requestedRoomId?: string; requestedUtility?: string }) {
  const initialUtility = requestedUtility === 'WATER' || requestedUtility === 'INTERNET' ? requestedUtility : 'ELECTRICITY';
  const [rooms, setRooms] = useState<Room[]>([]); const [unitId, setUnitId] = useState(''); const [utility, setUtility] = useState(initialUtility); const [value, setValue] = useState(''); const [recordedAt, setRecordedAt] = useState(new Date().toISOString().slice(0, 16)); const [context, setContext] = useState('MANUAL'); const [message, setMessage] = useState('');
  const [readings, setReadings] = useState<Json[]>([]); const [charges, setCharges] = useState<Json[]>([]); const [workspace, setWorkspace] = useState<Json | null>(null);
  const load = async (selectedUnit = unitId, selectedUtility = utility) => { if (!selectedUnit) return; if (selectedUtility === 'INTERNET') { setWorkspace(await apiFetch<Json>(`/api/v2/rooms/${encodeURIComponent(selectedUnit)}/utilities`)); return; } const [readingData, chargeData] = await Promise.all([apiFetch<Json[]>(`/api/v1/utilities/readings?unit_id=${encodeURIComponent(selectedUnit)}&utility_type=${selectedUtility}`), apiFetch<Json>(`/api/v1/utilities/charges?unit_id=${encodeURIComponent(selectedUnit)}&utility_type=${selectedUtility}`)]); setReadings(readingData); setCharges(Array.isArray(chargeData.charges) ? chargeData.charges : []); };
  useEffect(() => { setUtility(initialUtility); void apiFetch<Room[]>('/api/v1/units?limit=100&sort=id&direction=asc').then(data => { setRooms(data); const first = requestedRoomId && data.some(room => room.id === requestedRoomId) ? requestedRoomId : data[0]?.id ?? ''; setUnitId(first); return load(first, initialUtility); }).catch(() => setMessage('Rooms or utility data could not be loaded.')); }, [requestedRoomId, requestedUtility]);
  useEffect(() => { if (unitId) void load().catch(() => setMessage('Utility data could not be loaded.')); }, [unitId, utility]);
  const save = async () => { setMessage(''); try { await apiFetch('/api/v1/utilities/readings', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ unit_id: unitId, utility_type: utility, reading_value: value, recorded_at: new Date(recordedAt).toISOString(), context, reading_kind: context === 'CHECK_OUT' ? 'CLOSING' : context === 'CHECK_IN' ? 'OPENING' : 'INTERMEDIATE' }) }); setValue(''); setMessage('Reading saved'); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Reading could not be saved'); } };
  const internetPlans = Array.isArray(workspace?.internet_plans) ? workspace.internet_plans : []; const internetEquipment = Array.isArray(workspace?.internet_equipment) ? workspace.internet_equipment : []; const internetSubscriptions = Array.isArray(workspace?.internet_subscriptions) ? workspace.internet_subscriptions : []; const internetService = Array.isArray(workspace?.services) ? workspace.services.find(item => String(item.utility_type) === 'INTERNET') : null;
  return <div className="v2-content-stack"><Card title="Utilities" eyebrow="ROOM OPERATIONS" icon={<Activity />}><div className="v2-form-grid"><Field label="Room" value={unitId} select options={rooms.map(room => room.id)} onChange={setUnitId} /><Field label="Utility" value={utility} select options={['ELECTRICITY', 'WATER', 'INTERNET']} onChange={setUtility} /></div>{utility === 'INTERNET' ? <div className="v2-status-list"><StatusRow label="Service" value={String(internetService?.connection ?? internetService?.provider ?? 'AVAILABLE / NOT CONFIRMED')} />{internetPlans.map(plan => <StatusRow key={String(plan.id)} label={`${String(plan.plan_name ?? 'Plan')} · ${String(plan.service_brand ?? 'Provider')}`} value={`${plan.monthly_fee_centavos != null ? formatMoney(plan.monthly_fee_centavos) : 'FEE UNKNOWN'} · ${String(plan.advertised_speed_mbps ?? 'SPEED UNKNOWN')} Mbps`} />)}{internetEquipment.map(item => <StatusRow key={String(item.id)} label="Equipment" value={`${String(item.service_brand ?? 'UNKNOWN')} · ${String(item.equipment_type ?? item.technology ?? 'NOT PROVIDED')}`} />)}{internetSubscriptions.map(item => <StatusRow key={String(item.id)} label="Subscription" value={`${String(item.subscription_status ?? 'NOT CONFIRMED')} · ${String(item.activation_status ?? 'NOT CONFIRMED')}`} />)}{!internetPlans.length && !internetEquipment.length && !internetSubscriptions.length && <EmptyState title="No internet records" text="No building plan, equipment or tenancy subscription is recorded for this room." action="No action" onAction={() => undefined} />}</div> : <><div className="v2-form-grid"><Field label="Reading value" value={value} type="number" onChange={setValue} /><Field label="Reading date/time" value={recordedAt} type="datetime-local" onChange={setRecordedAt} /><Field label="Context" value={context} select options={['MANUAL', 'CHECK_IN', 'INTERMEDIATE', 'CHECK_OUT']} onChange={setContext} /></div><Button onClick={() => void save()}><Save size={15} />Save reading</Button>{message && <p className={message === 'Reading saved' ? 'v2-save-message' : 'v2-inline-error'}>{message}</p>}<div className="v2-status-list">{readings.map(reading => <div className="v2-person-relation" key={String(reading.id)}><strong>{String(reading.reading_value)} {utility === 'WATER' ? 'm³' : 'kWh'}</strong><small>{String(reading.context ?? 'MANUAL')} · {formatDate(reading.recorded_at)}{reading.tenancy_id ? ` · tenancy ${String(reading.tenancy_id)}` : ' · room-only'}</small></div>)}{charges.map(charge => <StatusRow key={`${String(charge.previous_reading_id)}-${String(charge.current_reading_id)}`} label={`${formatDate(charge.period_start)} → ${formatDate(charge.period_end)}`} value={`${String(charge.status)}${charge.amount_centavos != null ? ` · ${formatMoney(charge.amount_centavos)}` : ''}`} />)}</div></>}</Card></div>;
}

export { Button, Card, EmptyState, StatusBadge, Submenu, UtilitiesScreen }
